-- ============================================================================
-- 병원 안내자료(KB) 대량 시드 — RAG 품질 검증용(계획서 「RAG 골든 30~50 적중률」).
-- 성격: 정보성 「병원 이용 안내」만(승인 자료). 제외(계획 3.113): 의사 소개(staff.bio)·
--   진료시간/휴진 구체값(SCHED)·도구가 처리하는 예약 확인/취소 동작. 제한 자료(is_restricted)는
--   진단·처방·복용량 등 의료판단 → 봇이 원문만 보여주고 직원 연결.
-- ⚠️ 조각(kb_chunks)은 심지 않는다(임베딩 필요) — OpenAI 키 확보 후 재임베딩(approve 재실행 또는
--   reembed 배치)해야 실제 검색이 된다. 지금은 문서만 대량 적재.
-- 재실행 안전: 같은 title은 지우고 다시 넣는다(데모 26건과 title이 겹치지 않게 작성).
-- 데모 재시드(seed_demo_chat.sql)는 KB 전체를 지우므로, 이 파일은 그 뒤에 실행한다.
-- ============================================================================
do $$
declare v_admin uuid;
begin
  select id into v_admin from staff where role = 'admin' order by created_at limit 1;
  if v_admin is null then raise exception 'admin staff 없음 — seed_demo 먼저 실행'; end if;

  create temporary table _kb (title text, category text, content text, restricted bool, d int) on commit drop;
  insert into _kb (title, category, content, restricted, d) values
  -- ── 위치·주차 ──
  ('주차 요금·정산 안내','위치·주차', E'지하 2층 주차장은 최초 30분 무료, 이후 10분당 500원입니다.\n\n진료 시 1층 원무 창구에서 2시간 무료 등록을 해 드리며, 자세한 요금은 출차 정산기에서 확인하실 수 있습니다.', false, 22),
  ('장애인 주차구역 안내','위치·주차', E'지하 1·2층에 장애인 전용 주차구역이 마련돼 있습니다.\n\n장애인 주차 표지를 부착한 차량만 이용하실 수 있으며, 정산 감면은 원무 창구에서 안내해 드립니다.', false, 21),
  ('자전거·오토바이 주차 안내','위치·주차', E'자전거와 오토바이는 지상 1층 정문 옆 거치대를 이용해 주세요.\n\n원내 이동 통로에는 주차할 수 없습니다.', false, 20),
  ('건물·층별 이용 안내','위치·주차', E'가온빌딩 3층이 접수·진료·원무 공간입니다.\n\n엘리베이터는 정문 로비 안쪽에 있고, 각 진료과 위치는 3층 안내데스크에서 도와드립니다.', false, 19),
  ('셔틀버스 운행 안내','위치·주차', E'가온역과 병원을 오가는 무료 셔틀버스는 현재 운행하지 않습니다.\n\n지하철 3호선 가온역 2번 출구에서 도보 5분 거리이니 참고해 주세요.', false, 18),
  -- ── 예약·변경·취소 규칙 ──
  ('진료 예약 방법 안내','예약·변경·취소 규칙', E'진료 예약은 가온병원 앱에서 진료과·날짜·시간을 선택해 신청합니다.\n\n앱 사용이 어려우시면 1층 원무 창구에서 도와드립니다.', false, 17),
  ('당일 접수·현장 진료 안내','예약·변경·취소 규칙', E'예약 없이 방문하셔도 당일 접수로 진료가 가능하나, 예약 환자 우선이라 대기가 길 수 있습니다.\n\n원활한 진료를 위해 앱 예약을 권장합니다.', false, 16),
  ('예약 대기(취소분 알림) 안내','예약·변경·취소 규칙', E'원하는 시간이 마감된 경우 대기 신청을 해 두시면 취소분이 생길 때 앱 알림으로 안내해 드립니다.\n\n알림을 받으면 정해진 시간 안에 확정해 주세요.', false, 15),
  ('진료과·담당의 변경 안내','예약·변경·취소 규칙', E'예약한 진료과나 담당의를 바꾸고 싶으시면 기존 예약을 변경하거나 새로 예약해 주세요.\n\n변경 마감(전날 18시) 이후에는 상담(직원 확인)으로 연결됩니다.', false, 14),
  ('예약 확인·알림 안내','예약·변경·취소 규칙', E'예약 내역은 앱 ‘내 예약’에서 확인하실 수 있습니다.\n\n예약 하루 전과 당일 아침에 알림을 보내 드립니다.', false, 14),
  ('보호자 대리 예약·가족 연결 안내','예약·변경·취소 규칙', E'가족을 대신해 예약하려면 앱에서 가족 연결을 먼저 진행해 주세요.\n\n연결된 가족의 예약은 ‘누구의 예약인가요?’ 확인 후 진행됩니다.', false, 13),
  -- ── 검사 전 준비사항 ──
  ('CT(조영제) 검사 전 준비','검사 전 준비사항', E'조영제를 쓰는 CT는 검사 4시간 전부터 금식합니다(물은 소량 가능).\n\n조영제·해산물 알레르기, 신장질환, 당뇨약(메트포르민) 복용은 예약 시 꼭 알려 주세요.', true, 13),
  ('MRI 검사 전 준비·주의사항','검사 전 준비사항', E'몸속·몸에 금속(심박동기, 인공와우, 금속 클립, 문신·피어싱 등)이 있으면 미리 알려 주세요.\n\n폐소공포가 있으시면 예약 시 말씀해 주시고, 검사 중에는 움직이지 않아야 합니다.', false, 12),
  ('소변검사 안내','검사 전 준비사항', E'중간뇨(처음 소변은 버리고 중간 소변)를 받아 주세요.\n\n생리 중에는 결과에 영향이 있을 수 있으니 접수 시 알려 주세요.', false, 12),
  ('대변 잠혈검사 안내','검사 전 준비사항', E'제공된 채변 용기에 소량의 대변을 채취해 가져오세요.\n\n치질 출혈·생리 중에는 결과에 영향이 있을 수 있습니다.', false, 11),
  ('심전도·운동부하 검사 안내','검사 전 준비사항', E'심전도는 특별한 준비가 필요 없습니다.\n\n운동부하 검사는 편한 신발·운동복을 준비하시고, 검사 2시간 전 과식·흡연을 피해 주세요.', false, 11),
  ('폐기능 검사 안내','검사 전 준비사항', E'검사 전 흡연과 과식을 피해 주세요.\n\n기관지 확장제 등 흡입약 사용 여부를 접수 시 알려 주세요.', false, 10),
  ('골밀도 검사 안내','검사 전 준비사항', E'골밀도 검사는 금식이 필요 없습니다.\n\n최근 조영제 검사나 핵의학 검사를 받았다면 예약 시 알려 주세요.', false, 10),
  ('24시간 활동혈압·홀터 검사 안내','검사 전 준비사항', E'기기를 부착한 채 평소처럼 생활하시고, 물에 닿지 않게 주의하세요.\n\n다음 날 같은 시간에 병원에 방문해 기기를 반납합니다.', false, 9),
  ('갑상선 초음파 검사 안내','검사 전 준비사항', E'갑상선 초음파는 금식이 필요 없습니다.\n\n목걸이 등 목 부위 장신구는 검사 전에 빼 주세요.', false, 9),
  ('유방촬영(맘모그램) 검사 안내','검사 전 준비사항', E'생리 후 일주일 전후에 검사하면 통증이 덜합니다.\n\n검사 당일 겨드랑이·가슴에 파우더나 데오드란트를 바르지 마세요.', false, 8),
  ('위장조영(바륨) 검사 전 준비','검사 전 준비사항', E'검사 전날 밤 9시 이후 금식합니다.\n\n검사 후에는 바륨 배출을 위해 물을 충분히 드세요.', true, 8),
  ('알레르기(피부반응) 검사 안내','검사 전 준비사항', E'검사 3~7일 전부터 항히스타민제 복용을 중단해야 정확합니다.\n\n복용 중인 약이 있으면 예약 시 알려 주세요.', true, 7),
  ('경구 당부하 검사 안내','검사 전 준비사항', E'검사 전 8시간 금식 후 당액을 마시고 2시간 동안 채혈합니다.\n\n검사 중에는 흡연·과격한 활동을 피해 주세요.', true, 7),
  ('검체 채취 일반 안내','검사 전 준비사항', E'검체 용기는 원무 창구나 검사실에서 받으실 수 있습니다.\n\n채취 후에는 되도록 빨리 제출해 주세요.', false, 6),
  -- ── 진료비·증명서 ──
  ('진료비 수납 방법 안내','진료비·증명서', E'진료비는 1층 원무 창구, 무인 수납기, 또는 앱에서 카드·간편결제로 수납할 수 있습니다.\n\n수납 후 영수증과 진료비 세부내역서를 받으실 수 있습니다.', false, 6),
  ('영수증·세부내역서 재발급 안내','진료비·증명서', E'영수증과 세부내역서는 원무과 또는 앱에서 재발급받을 수 있습니다.\n\n연말정산용 의료비 내역은 국세청 간소화 서비스에서도 조회됩니다.', false, 5),
  ('비급여 진료비 안내','진료비·증명서', E'건강보험이 적용되지 않는 비급여 항목은 진료 전에 안내해 드립니다.\n\n비급여 항목과 금액은 원무과에서 확인하실 수 있습니다.', false, 5),
  ('진료비 분할·미수납 안내','진료비·증명서', E'진료비 납부가 어려우신 경우 원무과에 문의하시면 분할 납부를 상담해 드립니다.\n\n미수납 내역은 다음 방문 시 함께 정산됩니다.', false, 4),
  -- ── 증명서·서류 발급(신규 분류) ──
  ('진단서 발급 안내','증명서·서류 발급', E'진단서는 진료 후 담당 의사가 작성하며, 원무과에 신청하시면 발급해 드립니다.\n\n일반진단서·상해진단서 등 종류에 따라 비용과 소요 시간이 다릅니다.', false, 12),
  ('진료확인서·통원확인서 발급','증명서·서류 발급', E'진료확인서와 통원확인서는 원무과에서 즉시 발급 가능합니다.\n\n본인 확인을 위해 신분증을 지참해 주세요.', false, 11),
  ('입원·퇴원 확인서 발급','증명서·서류 발급', E'입퇴원 확인서는 원무과에서 발급합니다.\n\n보험 청구용으로 필요하시면 진료비 세부내역서와 함께 요청해 주세요.', false, 10),
  ('보험용·병사용 진단서 안내','증명서·서류 발급', E'보험사 제출용·병사용 진단서는 지정 서식이 있으면 서식을 지참해 주세요.\n\n진료 기록 확인이 필요해 발급까지 1~2일이 걸릴 수 있습니다.', false, 9),
  ('예방접종 증명서 발급','증명서·서류 발급', E'예방접종 증명서는 원무과에서 발급하거나 예방접종도우미 사이트에서 조회·출력할 수 있습니다.', false, 9),
  ('진료기록 사본 발급 안내','증명서·서류 발급', E'진료기록 사본은 본인 또는 법정대리인이 신분증을 지참해 원무과에 신청합니다.\n\n대리 발급 시 위임장과 가족관계 서류가 필요합니다.', false, 8),
  ('서류 대리 수령 안내','증명서·서류 발급', E'가족이 대신 서류를 받으려면 환자 신분증 사본, 대리인 신분증, 위임장, 가족관계 증명서가 필요합니다.\n\n서류 종류에 따라 추가 확인이 있을 수 있습니다.', false, 8),
  ('무인 제증명 발급기 안내','증명서·서류 발급', E'1층 로비의 무인 발급기에서 진료확인서·영수증 등 간단한 서류를 직접 출력할 수 있습니다.\n\n진단서 등 의사 작성 서류는 원무과에서 발급합니다.', false, 7),
  ('진료의뢰서(상급병원) 안내','증명서·서류 발급', E'상급병원 진료가 필요하면 담당 의사가 진료의뢰서를 작성해 드립니다.\n\n의뢰서가 있으면 상급병원에서 건강보험 적용에 도움이 됩니다.', false, 6),
  -- ── 입원·퇴원 안내(신규 분류) ──
  ('입원 수속 안내','입원·퇴원 안내', E'입원이 결정되면 원무과에서 입원 수속을 진행합니다.\n\n신분증과 보증금(해당 시), 복용 중인 약 목록을 준비해 주세요.', false, 12),
  ('입원 준비물 안내','입원·퇴원 안내', E'세면도구, 수건, 개인 컵, 편한 실내복, 슬리퍼를 준비해 주세요.\n\n귀중품은 되도록 가져오지 마시고, 부득이한 경우 개인 사물함을 이용하세요.', false, 11),
  ('병실 종류·차액 안내','입원·퇴원 안내', E'다인실은 건강보험이 적용되며, 상급병실(1·2인실)은 병실 차액이 발생합니다.\n\n병실 현황과 차액은 원무과에서 안내해 드립니다.', false, 10),
  ('보호자 상주·간병 안내','입원·퇴원 안내', E'보호자 1인 상주가 가능하며, 상주 보호자는 출입증을 받아 주세요.\n\n간병 서비스가 필요하면 원무과 또는 간호사실에 문의하세요.', false, 10),
  ('면회 시간·규칙 안내','입원·퇴원 안내', E'면회는 정해진 면회 시간에 가능하며, 감염 예방을 위해 인원이 제한될 수 있습니다.\n\n발열·호흡기 증상이 있으면 면회를 삼가 주세요.', false, 9),
  ('입원 중 식사·금식 안내','입원·퇴원 안내', E'입원 식사는 치료식 처방에 따라 제공됩니다.\n\n검사·수술로 금식이 필요한 경우 간호사가 미리 안내해 드립니다.', false, 9),
  ('낙상 예방 안내','입원·퇴원 안내', E'침대 난간을 올리고, 미끄럼 방지 슬리퍼를 신어 주세요.\n\n어지러울 때는 무리하지 말고 호출벨로 도움을 요청하세요.', false, 8),
  ('퇴원 절차·수납 안내','입원·퇴원 안내', E'퇴원이 결정되면 담당 간호사 안내에 따라 원무과에서 수납 후 퇴원합니다.\n\n퇴원약과 다음 외래 예약을 함께 확인해 주세요.', false, 8),
  ('입원 중 외출·외박 안내','입원·퇴원 안내', E'입원 중 외출·외박은 담당 의사 허가가 필요합니다.\n\n허가 없이 병원을 벗어나면 안전·치료에 문제가 생길 수 있습니다.', false, 7),
  -- ── 건강검진 안내(신규 분류) ──
  ('국가건강검진 대상·주기 안내','건강검진 안내', E'일반건강검진은 만 20세 이상 대상이며 보통 2년에 한 번(비사무직 등은 매년) 받습니다.\n\n대상 여부는 국민건강보험공단 안내문이나 건강iN에서 확인하실 수 있습니다.', false, 12),
  ('건강검진 예약·준비 안내','건강검진 안내', E'건강검진은 검진센터 예약 후 방문하며, 검사 전날 밤 9시 이후 금식이 필요합니다.\n\n복용 약이 있으면 예약 시 알려 주세요.', true, 11),
  ('위암 검진(위내시경) 안내','건강검진 안내', E'위암 검진은 만 40세 이상 2년마다 위내시경 또는 위장조영으로 시행합니다.\n\n검사 전날 밤 9시 이후 금식해 주세요.', true, 10),
  ('대장암 검진 안내','건강검진 안내', E'대장암 검진은 만 50세 이상 매년 분변잠혈검사로 시작하며, 이상 소견 시 대장내시경을 받습니다.\n\n채변 용기는 검진센터에서 받으실 수 있습니다.', false, 10),
  ('유방암 검진 안내','건강검진 안내', E'유방암 검진은 만 40세 이상 여성이 2년마다 유방촬영으로 받습니다.\n\n생리 후 일주일 전후에 검사하면 통증이 덜합니다.', false, 9),
  ('자궁경부암 검진 안내','건강검진 안내', E'자궁경부암 검진은 만 20세 이상 여성이 2년마다 받습니다.\n\n생리 기간은 피해 예약해 주세요.', false, 9),
  ('간암 검진 안내','건강검진 안내', E'간암 고위험군은 6개월마다 간초음파와 혈액검사(AFP)를 받습니다.\n\n대상 여부는 공단 안내를 확인하거나 진료 시 상담해 주세요.', false, 8),
  ('검진 후 추가검사·결과 상담 안내','건강검진 안내', E'검진 결과 이상 소견이 있으면 추가검사나 진료 예약을 안내해 드립니다.\n\n결과지는 우편·앱으로 통보되며 검진센터에서 상담받으실 수 있습니다.', false, 7),
  -- ── 예방접종 안내(신규 분류) ──
  ('독감(인플루엔자) 예방접종 안내','예방접종 안내', E'독감 예방접종은 보통 매년 가을~초겨울에 맞습니다.\n\n만 65세 이상 등은 국가 무료 접종 대상이며, 접종 가능 여부는 진료 후 안내해 드립니다.', false, 11),
  ('폐렴구균 예방접종 안내','예방접종 안내', E'폐렴구균 백신은 만 65세 이상에서 권장되며 종류에 따라 접종 간격이 다릅니다.\n\n기저질환이 있으면 접종 시기를 진료 시 상담해 주세요.', false, 10),
  ('대상포진 예방접종 안내','예방접종 안내', E'대상포진 백신은 만 50세 이상에서 권장됩니다.\n\n최근 대상포진을 앓았다면 접종 시기를 진료 시 상담해 주세요.', false, 10),
  ('파상풍·Tdap 예방접종 안내','예방접종 안내', E'파상풍·디프테리아·백일해(Tdap/Td)는 10년마다 추가접종이 권장됩니다.\n\n상처가 깊거나 오염된 경우 접종이 필요할 수 있습니다.', false, 9),
  ('A형·B형 간염 예방접종 안내','예방접종 안내', E'A형·B형 간염 백신은 항체 여부에 따라 접종합니다.\n\n접종 전 항체 검사를 함께 진행할 수 있습니다.', false, 9),
  ('자궁경부암(HPV) 예방접종 안내','예방접종 안내', E'HPV 백신은 권장 연령에서 접종하며 국가 지원 대상이 있습니다.\n\n접종 일정은 진료 후 안내해 드립니다.', false, 8),
  ('영유아 국가예방접종 안내','예방접종 안내', E'영유아 국가예방접종은 표준 일정에 따라 무료로 시행합니다.\n\n접종 수첩을 지참하시고, 일정은 진료 시 함께 확인해 드립니다.', false, 8),
  ('접종 후 주의사항 안내','예방접종 안내', E'접종 후 20~30분간 병원에서 이상반응을 관찰합니다.\n\n접종 부위 통증·미열은 흔하며, 심한 증상이 있으면 병원에 알려 주세요.', false, 7),
  -- ── 보험·수납 안내(신규 분류) ──
  ('실손보험 청구 절차 안내','보험·수납 안내', E'실손보험 청구에는 진료비 영수증과 세부내역서, 진단명이 필요합니다.\n\n원무과에서 서류를 발급받아 보험사에 제출하시면 됩니다.', false, 6),
  ('자동차보험(교통사고) 진료 안내','보험·수납 안내', E'교통사고 진료는 보험사 접수번호(지불보증)가 있으면 자동차보험으로 처리됩니다.\n\n접수번호가 없으면 우선 본인 부담 후 추후 정산할 수 있습니다.', false, 6),
  ('산재보험 진료 안내','보험·수납 안내', E'산업재해로 인한 진료는 산재 승인 후 산재보험으로 처리됩니다.\n\n승인 전에는 우선 본인 부담 후 정산이 필요할 수 있습니다.', false, 5),
  ('의료급여 이용 안내','보험·수납 안내', E'의료급여 수급권자는 신분 확인 후 의료급여로 진료를 받으실 수 있습니다.\n\n의뢰 절차가 필요한 경우 원무과에서 안내해 드립니다.', false, 5),
  ('연말정산 의료비 안내','보험·수납 안내', E'연말정산용 의료비는 국세청 연말정산 간소화 서비스에서 조회됩니다.\n\n누락분은 영수증으로 별도 제출하실 수 있습니다.', false, 4),
  -- ── 응급·야간 이용(신규 분류) ──
  ('응급 증상 대처 안내','응급·야간 이용', E'심한 흉통, 호흡곤란, 의식 저하, 심한 출혈 등은 즉시 119에 연락하거나 가까운 응급실을 이용하세요.\n\n가온병원은 응급실을 운영하지 않습니다.', false, 6),
  ('야간·휴일 이용 안내','응급·야간 이용', E'평일 야간과 일요일·공휴일은 진료하지 않습니다.\n\n야간·휴일에 문 여는 병의원은 119 또는 응급의료포털(e-gen)에서 확인하세요.', false, 6),
  ('소아 응급 대처 안내','응급·야간 이용', E'아이가 지속적인 고열, 처지거나 경련, 호흡곤란을 보이면 즉시 응급실을 이용하세요.\n\n야간에는 달빛어린이병원 정보를 확인하실 수 있습니다.', false, 5),
  ('약물 알레르기 응급 안내','응급·야간 이용', E'약 복용 후 두드러기, 얼굴·입술 부종, 호흡곤란 등 알레르기 반응이 나타나면 즉시 119에 연락하세요.\n\n남은 약과 약봉투를 함께 보여 주면 도움이 됩니다.', false, 5),
  -- ── 접근성 안내(신규 분류) ──
  ('휠체어·이동 지원 안내','접근성 안내', E'1층 안내데스크에서 휠체어를 무료로 대여합니다.\n\n거동이 불편하시면 안내 직원의 도움을 받으실 수 있습니다.', false, 6),
  ('장애인 편의시설 안내','접근성 안내', E'경사로, 장애인 화장실, 점자 안내가 마련돼 있습니다.\n\n필요하신 도움은 안내데스크에 말씀해 주세요.', false, 5),
  ('통역·수어 지원 안내','접근성 안내', E'외국인 환자를 위한 통역이나 청각장애인을 위한 수어 지원이 필요하면 미리 요청해 주세요.\n\n가능한 범위에서 지원해 드립니다.', false, 5),
  ('시각장애인 안내 지원','접근성 안내', E'시각장애인 안내가 필요하시면 안내데스크 직원이 진료실까지 동행해 드립니다.\n\n안내견 동반 출입이 가능합니다.', false, 4),
  -- ── 편의시설 ──
  ('원내 식당·카페·편의점 안내','편의시설', E'지하 1층에 카페와 편의점이 있습니다.\n\n입원 환자 식사는 병동에서 제공되며, 방문객은 카페를 이용하실 수 있습니다.', false, 6),
  ('현금인출기(ATM) 안내','편의시설', E'1층 로비에 현금인출기(ATM)가 있습니다.\n\n카드·간편결제 수납이 가능하니 참고해 주세요.', false, 5),
  ('물품보관함·분실물 안내','편의시설', E'1층에 물품보관함이 있으며, 분실물은 안내데스크에 보관합니다.\n\n분실물은 신분 확인 후 돌려드립니다.', false, 5),
  -- ── 자주 묻는 질문 ──
  ('진료 대기시간 안내','자주 묻는 질문', E'예약 시간에 맞춰 오시면 대기를 줄일 수 있으나, 진료 상황에 따라 지연될 수 있습니다.\n\n앱에서 대기 순번을 확인하실 수 있습니다.', false, 6),
  ('처방약 수령(원외약국) 안내','자주 묻는 질문', E'처방전을 받으면 병원 근처 약국에서 약을 받으실 수 있습니다.\n\n처방전은 발급일로부터 유효기간 내에 사용해 주세요.', false, 5),
  ('개인정보 열람·정정 안내','자주 묻는 질문', E'본인 진료·개인정보의 열람·정정은 원무과에 신청하실 수 있습니다.\n\n본인 확인을 위해 신분증이 필요합니다.', false, 5),
  ('반려동물 동반 출입 안내','자주 묻는 질문', E'감염 관리를 위해 반려동물은 원내 출입이 제한됩니다.\n\n장애인 안내견은 예외로 동반 가능합니다.', false, 4),
  -- ── 종합 안내(대용량 — 청킹/RAG 청크 실험용, 500자 단위로 여러 조각으로 나뉜다) ──
  ('가온병원 이용 종합 안내','위치·주차', E'가온병원 이용 종합 안내입니다. 병원 방문 전 알아두면 좋은 정보를 한데 모았습니다.\n\n[오시는 길] 가온병원은 서울특별시 강남구 테헤란로 123 가온빌딩 3층에 있습니다. 지하철은 3호선 가온역 2번 출구에서 도보 약 5분 거리입니다. 버스는 101번, 203번을 이용하시고 병원 앞 정류장에서 내리시면 됩니다. 자가용으로 오실 때는 내비게이션에 가온빌딩 또는 병원 주소를 입력하세요. 가온역과 병원을 오가는 무료 셔틀버스는 현재 운행하지 않습니다.\n\n[주차] 주차는 가온빌딩 지하 2층 주차장을 이용하시면 됩니다. 최초 30분은 무료이며 이후 10분당 500원이 부과됩니다. 진료를 받으신 경우 1층 원무 창구에서 2시간 무료 주차 등록을 도와드립니다. 장애인 전용 주차구역은 지하 1층과 2층에 마련돼 있으며, 장애인 주차 표지를 부착한 차량만 이용하실 수 있습니다. 자전거와 오토바이는 지상 1층 정문 옆 거치대를 이용해 주시고, 원내 이동 통로에는 주차할 수 없습니다.\n\n[예약과 접수] 진료 예약은 가온병원 앱에서 진료과와 날짜, 시간을 선택해 신청하실 수 있습니다. 예약 후 방문하시면 앱의 QR 코드로 바로 접수됩니다. 앱 사용이 어려우시면 3층 원무 창구에서 접수를 도와드립니다. 처음 방문(초진)하시는 경우 신분증을 지참해 주세요. 예약 없이 오셔도 당일 접수로 진료가 가능하나 예약 환자가 우선이라 대기가 길 수 있습니다. 예약 변경과 취소는 진료 전날 18시까지 앱에서 직접 하실 수 있고, 그 이후에는 상담(직원 확인)으로 연결됩니다.\n\n[수납과 서류] 진료비는 3층 원무 창구, 무인 수납기, 또는 앱에서 카드와 간편결제로 수납하실 수 있습니다. 수납 후 영수증과 진료비 세부내역서를 받으실 수 있으며, 실손보험 청구가 필요하시면 원무과에 말씀해 주세요. 건강보험이 적용되지 않는 비급여 항목은 진료 전에 안내해 드립니다. 진단서, 소견서, 진료확인서 등 각종 서류는 원무과에 신청하시면 발급해 드리며, 진단서 등 의사 작성 서류는 1~2일이 걸릴 수 있습니다.\n\n[편의시설] 3층에 수유실이 있고, 1층 안내데스크에서 휠체어를 무료로 대여합니다. 대기실에서는 무료 와이파이(GAON-GUEST)를 이용하실 수 있습니다. 지하 1층에는 카페와 편의점이 있으며, 1층 로비에 현금인출기와 물품보관함이 마련돼 있습니다. 경사로, 장애인 화장실, 점자 안내가 갖춰져 있고, 안내견 동반 출입이 가능합니다.\n\n[진료 이용] 요일별 진료시간은 상담봇에 ''진료시간''이라고 물어보시면 정확히 안내해 드리고, 앱의 예약 화면에서도 확인하실 수 있습니다. 특정 진료과·담당의의 진료 요일도 앱에서 확인해 주세요. 감염 예방을 위해 원내 마스크 착용을 권장하며, 발열·기침 증상이 있으면 입구 선별 안내를 따라 주세요.\n\n[응급 상황] 심한 흉통, 호흡곤란, 의식 저하, 심한 출혈 등 응급 상황에는 가온병원에 응급실이 없으므로 즉시 119에 연락하거나 가까운 응급실을 이용하세요. 야간·휴일에 문 여는 병의원은 119나 응급의료포털(e-gen)에서 확인하실 수 있습니다.\n\n[문의와 안내 한계] 그 밖의 궁금한 점은 3층 안내데스크나 원무과에 문의해 주세요. 진단, 처방, 약 복용량 조절, 검사 결과 해석 등 의료 판단이 필요한 내용은 담당 의사 진료가 필요하며 상담봇으로는 안내해 드리기 어렵습니다. 이런 문의는 직원 상담으로 연결해 드립니다.', false, 24),
  ('검사 준비사항 종합 안내','검사 전 준비사항', E'검사 종류별 준비사항을 한데 모은 안내입니다. 예약하신 검사에 해당하는 부분을 확인해 주세요.\n\n[내시경] 위내시경은 검사 전날 밤 9시 이후 물을 포함해 금식합니다. 복용 중인 혈압약은 검사 당일 아침 소량의 물과 함께 드셔도 됩니다. 대장내시경은 검사 3일 전부터 씨앗, 견과류, 잡곡을 피하고 전날 저녁부터 장정결제를 복용합니다. 자세한 복용 시간은 예약 시 안내해 드립니다.\n\n[초음파] 복부 초음파는 검사 전 8시간 금식이 필요하며 물은 소량 가능합니다. 오전 검사는 전날 밤 12시부터 금식하시면 됩니다. 갑상선 초음파는 금식이 필요 없고, 목 부위 장신구는 검사 전에 빼 주세요.\n\n[혈액·소변·대변] 공복 혈액검사는 8~12시간 금식 후 진행하며 물은 마셔도 됩니다. 소변검사는 중간뇨를 받아 주세요. 대변 잠혈검사는 채변 용기에 소량 채취해 가져오시고, 치질 출혈이나 생리 중에는 결과에 영향이 있을 수 있습니다.\n\n[영상] 조영제를 쓰는 CT는 검사 4시간 전부터 금식하며, 조영제·해산물 알레르기, 신장질환, 당뇨약(메트포르민) 복용을 예약 시 꼭 알려 주세요. MRI는 몸속·몸에 금속(심박동기, 인공와우, 금속 클립, 문신·피어싱 등)이 있으면 미리 알려 주시고, 폐소공포가 있으면 예약 시 말씀해 주세요. 유방촬영은 생리 후 일주일 전후에 하면 통증이 덜하고, 검사 당일 겨드랑이·가슴에 파우더나 데오드란트를 바르지 마세요.\n\n[기능 검사] 심전도는 특별한 준비가 없습니다. 운동부하 검사는 편한 신발과 운동복을 준비하고 검사 2시간 전 과식·흡연을 피하세요. 폐기능 검사도 흡연과 과식을 피하고 흡입약 사용 여부를 알려 주세요. 24시간 활동혈압·홀터 검사는 기기를 부착한 채 평소처럼 생활하되 물에 닿지 않게 하고 다음 날 같은 시간에 반납합니다. 경구 당부하 검사는 8시간 금식 후 당액을 마시고 2시간 동안 채혈합니다.\n\n[공통 주의] 복용 중인 약이 있으면 예약 시 미리 알려 주세요. 검사에 따라 복용을 잠시 중단해야 할 수 있습니다. 검체 용기는 원무 창구나 검사실에서 받으실 수 있고, 채취 후에는 되도록 빨리 제출해 주세요. 검사 결과의 해석은 담당 의사 진료가 필요하며 상담봇으로는 안내해 드리기 어렵습니다.', true, 23),
  ('건강검진 종합 안내','건강검진 안내', E'국가건강검진과 암검진을 한데 모은 안내입니다. 대상 여부는 국민건강보험공단 안내문이나 건강iN에서 확인하실 수 있습니다.\n\n[일반건강검진] 만 20세 이상이 대상이며 보통 2년에 한 번, 비사무직 등은 매년 받습니다. 검진은 검진센터 예약 후 방문하며 검사 전날 밤 9시 이후 금식이 필요합니다. 복용 약이 있으면 예약 시 알려 주세요.\n\n[위암 검진] 만 40세 이상이 2년마다 위내시경 또는 위장조영으로 받습니다. 검사 전날 밤 9시 이후 금식해 주세요.\n\n[대장암 검진] 만 50세 이상이 매년 분변잠혈검사로 시작하며, 이상 소견이 있으면 대장내시경을 받습니다. 채변 용기는 검진센터에서 받으실 수 있습니다.\n\n[유방암 검진] 만 40세 이상 여성이 2년마다 유방촬영으로 받습니다. 생리 후 일주일 전후에 검사하면 통증이 덜합니다.\n\n[자궁경부암 검진] 만 20세 이상 여성이 2년마다 받으며 생리 기간은 피해 예약해 주세요.\n\n[간암 검진] 간암 고위험군은 6개월마다 간초음파와 혈액검사(AFP)를 받습니다. 대상 여부는 공단 안내를 확인하거나 진료 시 상담해 주세요.\n\n[검진 이후] 결과지는 우편이나 앱으로 통보되며 검진센터에서 상담받으실 수 있습니다. 이상 소견이 있으면 추가검사나 진료 예약을 안내해 드립니다. 검진 결과지가 필요하시면 검진센터나 원무과에서 재발급받을 수 있습니다.', true, 22),
  ('입원 생활 종합 안내','입원·퇴원 안내', E'입원부터 퇴원까지 알아두면 좋은 내용을 모았습니다.\n\n[입원 수속] 입원이 결정되면 원무과에서 수속을 진행합니다. 신분증과 보증금(해당 시), 복용 중인 약 목록을 준비해 주세요. 다인실은 건강보험이 적용되고 상급병실(1·2인실)은 병실 차액이 발생하며, 병실 현황과 차액은 원무과에서 안내해 드립니다.\n\n[준비물] 세면도구, 수건, 개인 컵, 편한 실내복, 슬리퍼를 준비해 주세요. 귀중품은 되도록 가져오지 마시고 부득이한 경우 개인 사물함을 이용하세요.\n\n[보호자와 면회] 보호자 1인 상주가 가능하며 상주 보호자는 출입증을 받아 주세요. 간병 서비스가 필요하면 원무과나 간호사실에 문의하세요. 면회는 정해진 면회 시간에 가능하고 감염 예방을 위해 인원이 제한될 수 있으며, 발열·호흡기 증상이 있으면 면회를 삼가 주세요.\n\n[생활과 안전] 입원 식사는 치료식 처방에 따라 제공되며, 검사·수술로 금식이 필요하면 간호사가 미리 안내해 드립니다. 낙상 예방을 위해 침대 난간을 올리고 미끄럼 방지 슬리퍼를 신어 주세요. 어지러울 때는 무리하지 말고 호출벨로 도움을 요청하세요. 입원 중 외출·외박은 담당 의사 허가가 필요합니다.\n\n[퇴원] 퇴원이 결정되면 담당 간호사 안내에 따라 원무과에서 수납 후 퇴원합니다. 퇴원약과 다음 외래 예약을 함께 확인해 주세요. 입퇴원 확인서 등 서류가 필요하시면 원무과에 요청하시면 발급해 드립니다.', false, 21),
  ('증명서·서류 발급 종합 안내','증명서·서류 발급', E'가온병원에서 발급하는 서류를 한데 모은 안내입니다. 대부분 원무과에서 신청하실 수 있습니다.\n\n[의사 작성 서류] 진단서는 진료 후 담당 의사가 작성하며 일반진단서, 상해진단서 등 종류에 따라 비용과 소요 시간이 다릅니다. 보험사 제출용이나 병사용 진단서는 지정 서식이 있으면 서식을 지참해 주세요. 소견서와 진료의뢰서도 담당 의사가 작성하며, 상급병원 진료가 필요할 때 의뢰서가 있으면 건강보험 적용에 도움이 됩니다. 의사 작성 서류는 진료 기록 확인이 필요해 발급까지 1~2일이 걸릴 수 있습니다.\n\n[즉시 발급 서류] 진료확인서, 통원확인서, 입퇴원 확인서는 원무과에서 즉시 발급 가능합니다. 진료비 영수증과 세부내역서는 원무과나 앱에서 재발급받을 수 있고, 1층 로비의 무인 발급기에서 진료확인서·영수증 등 간단한 서류를 직접 출력하실 수도 있습니다.\n\n[진료기록과 대리 수령] 진료기록 사본은 본인 또는 법정대리인이 신분증을 지참해 원무과에 신청합니다. 가족이 대신 서류를 받으려면 환자 신분증 사본, 대리인 신분증, 위임장, 가족관계 증명서가 필요하며 서류 종류에 따라 추가 확인이 있을 수 있습니다.\n\n[기타] 예방접종 증명서는 원무과에서 발급하거나 예방접종도우미 사이트에서 조회·출력할 수 있습니다. 건강검진 결과지는 검진센터나 원무과에서 재발급받을 수 있습니다. 연말정산용 의료비는 국세청 간소화 서비스에서 조회되며 누락분은 영수증으로 별도 제출하실 수 있습니다.', false, 20),

  ('가온병원 자주 묻는 질문 모음(전체)','자주 묻는 질문', E'가온병원 이용 중 자주 묻는 질문을 모았습니다. 궁금한 항목을 찾아 참고해 주세요.\n\nQ. 병원은 어디에 있나요? A. 서울특별시 강남구 테헤란로 123 가온빌딩 3층입니다. 3호선 가온역 2번 출구에서 도보 5분 거리이며, 버스는 101·203번을 이용하시면 됩니다.\n\nQ. 주차는 어떻게 하나요? A. 지하 2층 주차장을 이용하시고 최초 30분은 무료입니다. 진료를 받으시면 1층 원무 창구에서 2시간 무료 등록을 도와드립니다.\n\nQ. 예약은 어떻게 하나요? A. 가온병원 앱에서 진료과와 날짜, 시간을 선택해 신청하실 수 있습니다. 앱 사용이 어려우시면 원무 창구에서 도와드립니다.\n\nQ. 예약을 바꾸거나 취소하고 싶어요. A. 진료 전날 18시까지 앱에서 직접 하실 수 있고, 그 이후에는 상담(직원 확인)으로 연결됩니다.\n\nQ. 예약 없이 가도 진료가 되나요? A. 당일 접수로 가능하나 예약 환자가 우선이라 대기가 길 수 있습니다. 앱 예약을 권장합니다.\n\nQ. 진료 시간은 어떻게 되나요? A. 상담봇에 ''진료시간''이라고 물어보시면 요일별 진료시간을 정확히 안내해 드리고, 앱의 예약 화면에서도 확인하실 수 있습니다.\n\nQ. 진료비는 어떻게 내나요? A. 1층 원무 창구, 무인 수납기, 앱에서 카드와 간편결제로 수납하실 수 있습니다. 수납 후 영수증과 세부내역서를 받으실 수 있습니다.\n\nQ. 실손보험 청구 서류가 필요해요. A. 진료비 영수증과 세부내역서, 진단명이 필요합니다. 원무과에서 발급받아 보험사에 제출하시면 됩니다.\n\nQ. 진단서는 어떻게 받나요? A. 진료 후 담당 의사가 작성하며 원무과에 신청하시면 발급해 드립니다. 종류에 따라 1~2일이 걸릴 수 있습니다.\n\nQ. 진료확인서·통원확인서는요? A. 원무과에서 즉시 발급 가능하며 신분증을 지참해 주세요.\n\nQ. 처방전을 잃어버렸어요. A. 진료 후 원무과에서 재발급 받을 수 있으며 유효기간 내에만 가능합니다. 재발급 시 신분증이 필요합니다.\n\nQ. 약은 어디서 받나요? A. 처방전을 받으시면 병원 근처 약국에서 약을 받으실 수 있습니다.\n\nQ. 검사 전에 금식해야 하나요? A. 검사에 따라 다릅니다. 위내시경·공복 혈액검사·복부 초음파 등은 금식이 필요하고, 갑상선 초음파·골밀도 등은 필요 없습니다. 예약하신 검사의 준비사항을 확인해 주세요.\n\nQ. 건강검진은 어떻게 받나요? A. 검진센터 예약 후 방문하며 검사 전날 밤 9시 이후 금식이 필요합니다. 대상 여부는 국민건강보험공단 안내나 건강iN에서 확인하실 수 있습니다.\n\nQ. 예방접종을 하고 싶어요. A. 독감, 폐렴구균, 대상포진 등 성인 접종과 영유아 국가예방접종을 시행합니다. 접종 가능 여부와 시기는 진료 후 안내해 드립니다.\n\nQ. 입원하려면 무엇이 필요하나요? A. 입원이 결정되면 원무과에서 수속하며 신분증과 복용 약 목록을 준비해 주세요. 병실은 다인실(보험 적용)과 상급병실(차액 발생)이 있습니다.\n\nQ. 면회는 언제 되나요? A. 정해진 면회 시간에 가능하며 감염 예방을 위해 인원이 제한될 수 있습니다. 발열·호흡기 증상이 있으면 삼가 주세요.\n\nQ. 휠체어를 빌릴 수 있나요? A. 1층 안내데스크에서 무료로 대여합니다. 거동이 불편하시면 안내 직원의 도움을 받으실 수 있습니다.\n\nQ. 수유실이나 편의점이 있나요? A. 3층에 수유실이 있고 지하 1층에 카페와 편의점, 1층 로비에 현금인출기와 물품보관함이 있습니다. 대기실에서 무료 와이파이(GAON-GUEST)를 이용하실 수 있습니다.\n\nQ. 응급 상황에는 어떻게 하나요? A. 가온병원은 응급실을 운영하지 않습니다. 심한 흉통·호흡곤란·의식 저하 등 응급 상황에는 즉시 119에 연락하거나 가까운 응급실을 이용하세요.\n\nQ. 반려동물과 함께 가도 되나요? A. 감염 관리를 위해 원내 출입이 제한됩니다. 장애인 안내견은 예외로 동반 가능합니다.\n\nQ. 진료기록 사본이 필요해요. A. 본인 또는 법정대리인이 신분증을 지참해 원무과에 신청합니다. 대리 발급 시 위임장과 가족관계 서류가 필요합니다.\n\nQ. 개인정보 열람·정정은 어떻게 하나요? A. 본인 확인 후 원무과에 신청하실 수 있으며 신분증이 필요합니다.\n\nQ. 증상만 말하면 무슨 병인지 알 수 있나요? A. 증상만으로는 진단이 어렵습니다. 진단, 처방, 약 복용량, 검사 결과 해석 등은 담당 의사 진료가 필요하며 상담봇으로는 안내해 드리기 어려워 직원 상담으로 연결해 드립니다.', false, 25),

  -- ── 진료 이용·시간 ──
  -- ⚠️ '진료시간·휴진 안내'·'점심시간 진료 안내' KB 문서는 삭제됨(KBADM-EDITOR-17, 2026-09-08).
  --    요일별 진료시간·점심시간은 hospital_hours DB 단일원본에서 읽어 상담봇 intent 프리체크
  --    (intent_precheck.detect_intent/format_hours)가 정확히 답한다 — KB에 중복 저장하면 두루뭉술한
  --    "평일 낮…앱 확인" 답이 되살아나므로 금지. 아래는 시간값이 아닌 일반 안내만 남긴다.
  ('진료·접수 마감 안내','진료 이용·시간', E'접수는 진료 마감 시간보다 일찍 마감될 수 있습니다.\n\n마감에 임박해 오시면 당일 진료가 어려울 수 있으니 앱 예약 시간을 확인하고 여유 있게 방문해 주세요.', false, 30),
  ('공휴일·연휴 진료 안내','진료 이용·시간', E'일요일과 공휴일에는 진료하지 않습니다. 명절 연휴 등 특별 휴진은 병원 공지와 앱 알림으로 미리 안내해 드립니다.\n\n휴일에 진료가 필요하시면 119나 응급의료포털(e-gen)에서 문 여는 병의원을 확인해 주세요.', false, 30),
  ('초진·재진 안내','진료 이용·시간', E'처음 방문(초진)하실 때는 신분증을 지참해 주세요. 접수 시 기본 정보를 등록합니다.\n\n이전에 방문하신 적이 있으면(재진) 예약 또는 접수 후 바로 진료를 받으실 수 있습니다.', false, 30),
  ('진료 순서·지연 안내','진료 이용·시간', E'진료는 예약과 접수 순서에 따라 진행되며, 진료 상황에 따라 예약 시간보다 지연될 수 있습니다.\n\n앱에서 대기 순번을 확인하실 수 있고, 오래 지연되면 안내데스크에 문의해 주세요.', false, 30),
  -- ── 진료과 안내(어느 과로 가야 하는지 — 진단 아님, 진료 범위 안내) ──
  ('어느 과로 가야 할지 안내','진료과 안내', E'어떤 과를 가야 할지 모르실 때는 AI 상담봇과 대화하며 증상을 알려 주시면 알맞은 진료과를 안내해 드립니다.\n\n판단이 어려우면 내과나 가정의학과 진료를 먼저 받고 필요한 과를 안내받으실 수도 있습니다. 최종 선택은 환자분이 확인하시면 됩니다.', false, 29),
  ('진료과 안내 — 내과','진료과 안내', E'내과는 감기·기침·소화불량·복통·설사, 발열, 피로감과 고혈압·당뇨 같은 만성질환 등 몸 전반의 내과적 문제를 봅니다.\n\n어느 과인지 애매할 때 먼저 내과 진료를 받고 필요한 과를 안내받으실 수 있습니다.', false, 29),
  ('진료과 안내 — 가정의학과','진료과 안내', E'가정의학과는 특정 과를 정하기 어려운 다양한 증상, 건강검진, 예방접종, 만성질환의 꾸준한 관리를 폭넓게 봅니다.\n\n어느 과를 가야 할지 모르실 때 상담하기 좋은 과입니다.', false, 29),
  ('진료과 안내 — 정형외과','진료과 안내', E'정형외과는 뼈·관절·근육·인대 문제를 봅니다. 허리·목·무릎·어깨 통증, 골절, 삐끗함, 관절염 등이 해당합니다.\n\n다치거나 아픈 부위를 말씀해 주시면 접수에 도움이 됩니다.', false, 29),
  ('진료과 안내 — 신경과','진료과 안내', E'신경과는 두통, 어지럼, 손발 저림·떨림, 경련, 기억력 저하 등 뇌와 신경에서 오는 증상을 봅니다.\n\n증상이 언제부터 어떻게 나타나는지 알려 주시면 진료에 도움이 됩니다.', false, 29),
  ('진료과 안내 — 피부과','진료과 안내', E'피부과는 발진, 가려움, 두드러기, 여드름, 습진, 탈모, 손발톱 문제 등 피부·모발 관련 증상을 봅니다.\n\n증상 부위와 시작 시기를 알려 주시면 진료에 도움이 됩니다.', false, 29),
  ('진료과 안내 — 이비인후과','진료과 안내', E'이비인후과는 코막힘·콧물, 목 아픔, 기침, 귀 통증·먹먹함, 이명, 어지럼, 목소리 변화 등 귀·코·목 증상을 봅니다.\n\n어느 부위가 불편한지 말씀해 주시면 접수에 도움이 됩니다.', false, 29),
  ('진료과 안내 — 안과','진료과 안내', E'안과는 눈 충혈, 시력 저하, 눈물·눈부심, 다래끼, 눈 이물감 등 눈과 관련한 증상을 봅니다.\n\n증상이 한쪽인지 양쪽인지, 언제부터인지 알려 주시면 도움이 됩니다.', false, 29),
  ('진료과 안내 — 비뇨의학과','진료과 안내', E'비뇨의학과는 배뇨 불편, 빈뇨, 혈뇨, 전립선, 요로결석 등 비뇨·생식기 관련 증상을 봅니다.\n\n남녀 모두 진료하며, 불편한 증상을 편하게 말씀해 주시면 됩니다.', false, 29),
  ('진료과 안내 — 산부인과','진료과 안내', E'산부인과는 생리 관련 문제, 부인과 검진, 임신·산전 진료 등 여성 건강을 봅니다.\n\n검진·상담 목적도 예약하실 수 있으며, 불편한 점을 편하게 말씀해 주세요.', false, 29),
  ('진료과 안내 — 소아청소년과','진료과 안내', E'소아청소년과는 만 18세 이하 어린이·청소년의 발열, 기침, 배탈, 성장·발달 등 건강 문제를 봅니다.\n\n보호자가 함께 오셔서 증상과 경과를 알려 주시면 진료에 도움이 됩니다.', false, 29),
  ('진료과 안내 — 정신건강의학과','진료과 안내', E'정신건강의학과는 불면, 우울감, 불안, 스트레스 등 마음 건강에 관한 상담과 진료를 합니다.\n\n편하게 이야기하실 수 있으며, 상담 내용은 안전하게 보호됩니다.', false, 29),
  ('진료과 안내 — 재활의학과','진료과 안내', E'재활의학과는 통증, 마비, 근육·관절 기능 저하의 재활과 물리치료·도수치료 연계를 봅니다.\n\n다친 경위나 불편한 동작을 알려 주시면 진료에 도움이 됩니다.', false, 29),
  ('진료과 안내 — 외과','진료과 안내', E'외과는 상처·종기, 탈장, 항문 질환 등 수술적 치료가 필요할 수 있는 문제를 봅니다.\n\n증상 부위와 상태를 말씀해 주시면 접수에 도움이 됩니다.', false, 29),
  -- ── 앱·디지털 이용 ──
  ('가온병원 앱 설치·회원가입 안내','앱·디지털 이용', E'가온병원 앱은 앱스토어나 구글 플레이에서 ‘가온병원’으로 검색해 설치하실 수 있습니다.\n\n회원가입은 휴대폰 본인확인 후 진행되며, 가입하시면 예약·접수·알림·사전문진을 이용하실 수 있습니다.', false, 28),
  ('앱 로그인·비밀번호 찾기 안내','앱·디지털 이용', E'앱 로그인은 가입하신 휴대폰 번호와 비밀번호로 하실 수 있습니다.\n\n비밀번호가 기억나지 않으시면 로그인 화면의 비밀번호 찾기에서 휴대폰 본인확인 후 다시 설정하실 수 있습니다.', false, 28),
  ('가족(보호자) 연결 안내','앱·디지털 이용', E'가족의 진료를 대신 예약하거나 확인하려면 앱에서 가족 연결을 먼저 진행해 주세요.\n\n연결 후에는 예약할 때 누구의 예약인지 선택할 수 있습니다. 연결·해제는 앱 설정에서 관리하실 수 있습니다.', false, 28),
  ('QR 접수 사용법 안내','앱·디지털 이용', E'예약 후 병원에 오시면 앱의 예약 화면에 있는 QR 코드를 접수처 단말에 대어 바로 접수하실 수 있습니다.\n\nQR 접수가 어려우시면 3층 원무 창구에서 도와드립니다.', false, 28),
  ('사전문진 작성 안내','앱·디지털 이용', E'예약이 확정되면 방문 전에 앱에서 간단한 사전문진을 작성하실 수 있습니다.\n\n작성한 내용은 진료 시 담당 의사에게 전달됩니다. 도착·대기 중에는 수정할 수 있고 진료가 시작되면 읽기 전용이 됩니다.', false, 28),
  ('앱 알림 설정 안내','앱·디지털 이용', E'예약 하루 전과 당일 아침 알림, 순서 안내 등은 앱 알림으로 받으실 수 있습니다.\n\n알림 종류는 앱 설정에서 켜고 끄실 수 있고, 휴대폰 자체 알림 권한도 켜 두셔야 도착합니다.', false, 28),
  ('진료내역·결과 앱 조회 안내','앱·디지털 이용', E'지난 예약과 방문 내역, 병원이 공개한 방문 안내는 앱에서 확인하실 수 있습니다.\n\n자세한 진단기록 전체나 검사 결과 해석은 진료를 통해 확인하시는 것이 정확합니다.', false, 28),
  -- ── 위치·교통 추가 ──
  ('대중교통 이용 안내','위치·주차', E'지하철은 3호선 가온역 2번 출구에서 도보 약 5분 거리입니다.\n\n버스는 101번과 203번을 이용하시고 병원 앞 정류장에서 내리시면 됩니다.', false, 18),
  ('전기차·경차 주차 안내','위치·주차', E'전기차 충전 구역과 경차 전용 구역 운영 여부는 지하 주차장 안내를 따라 주세요.\n\n요금 감면 대상 여부는 1층 원무 창구에서 확인해 드립니다.', false, 18),
  -- ── 예약·변경·취소 추가 ──
  ('예약 변경 방법 안내','예약·변경·취소 규칙', E'예약 시간을 바꾸고 싶으시면 앱의 내 예약에서 예약 변경을 선택해 다른 날짜·시간으로 옮기실 수 있습니다.\n\n변경 마감(진료 전날 18시) 이후에는 상담(직원 확인)으로 연결됩니다.', false, 17),
  ('예약 취소 방법 안내','예약·변경·취소 규칙', E'예약을 취소하시려면 앱의 내 예약에서 예약 취소를 선택해 주세요.\n\n취소 마감(진료 전날 18시) 이후에는 앱에서 바로 취소되지 않고 상담(직원 확인)으로 연결됩니다.', false, 17),
  ('예약 부도(노쇼) 안내','예약·변경·취소 규칙', E'예약하신 뒤 연락 없이 방문하지 않으시면 예약 부도로 기록될 수 있습니다.\n\n방문이 어려우시면 미리 예약을 취소하거나 변경해 주시면 다른 분이 이용하실 수 있습니다.', false, 17),
  -- ── 편의시설 추가 ──
  ('수유실·기저귀 교환대 안내','편의시설', E'3층에 수유실이 마련돼 있습니다. 기저귀 교환대 위치는 안내데스크에서 도와드립니다.\n\n편하게 이용하실 수 있도록 필요하시면 직원에게 말씀해 주세요.', false, 8),
  ('원내 와이파이 안내','편의시설', E'대기실에서 무료 와이파이(GAON-GUEST)를 이용하실 수 있습니다.\n\n연결이 어려우시면 안내데스크에서 도와드립니다.', false, 8),
  ('금연·흡연구역 안내','편의시설', E'병원 건물 내부는 전체 금연입니다.\n\n흡연이 필요하시면 건물 외부의 지정된 구역을 이용해 주세요.', false, 8),
  -- ── 감염관리·방문수칙 ──
  ('마스크 착용·발열 선별 안내','감염관리·방문수칙', E'감염 예방을 위해 원내에서는 마스크 착용을 권장합니다.\n\n발열이나 기침 증상이 있으시면 입구의 선별 안내를 따라 주세요.', false, 7),
  ('호흡기 증상 방문 안내','감염관리·방문수칙', E'발열·기침·인후통 등 호흡기 증상이 있으시면 방문 전 앱이나 전화로 문의해 주시면 안내해 드립니다.\n\n방문 시에는 마스크를 착용하고 입구 안내를 따라 주세요.', false, 7),
  ('보호자·방문객 수칙 안내','감염관리·방문수칙', E'감염 예방을 위해 방문 인원이 제한될 수 있습니다.\n\n발열·호흡기 증상이 있는 분은 방문을 삼가 주시고, 손 위생에 협조해 주세요.', false, 7),
  -- ── 자주 묻는 질문 추가 ──
  ('처방전 재발급 안내','자주 묻는 질문', E'처방전을 잃어버리셨으면 진료 후 원무과에서 재발급받으실 수 있습니다.\n\n유효기간 안에서만 가능하며 재발급 시 신분증이 필요합니다.', false, 4),
  ('타 병원 검사기록 지참 안내','자주 묻는 질문', E'다른 병원에서 받은 검사 결과지나 영상(CD)을 가져오시면 진료에 참고할 수 있습니다.\n\n중복 검사를 줄이는 데 도움이 되니 있으시면 지참해 주세요.', false, 4),
  ('외국인 진료·건강보험 안내','자주 묻는 질문', E'외국인도 진료받으실 수 있습니다. 건강보험 적용 여부는 체류 자격과 가입 상태에 따라 다릅니다.\n\n자세한 사항은 원무과에서 확인해 드립니다. 신분증(외국인등록증 등)을 지참해 주세요.', false, 4),
  ('현금영수증·카드 결제 안내','자주 묻는 질문', E'진료비는 카드, 간편결제, 현금으로 수납하실 수 있습니다.\n\n현금영수증이 필요하시면 수납 시 말씀해 주세요.', false, 4),

  -- ── 큰 안내문(여러 문단 → 여러 조각으로 청킹, RAG 검증용) ──
  ('처음 오시는 분을 위한 방문 준비 종합 안내','자주 묻는 질문', E'가온병원은 예약 진료를 기본으로 합니다. 가온병원 앱에서 진료과·날짜·시간을 골라 예약하시면 대기 시간을 줄일 수 있습니다. 앱 사용이 어려우시면 3층 원무 창구에서 도와드리며, 예약 없이 오셔도 당일 접수로 진료가 가능하나 예약 환자 우선이라 대기가 길어질 수 있습니다.\n\n방문하실 때는 본인 확인을 위해 신분증을 꼭 지참해 주세요. 자녀나 어르신의 진료를 대신 오실 때는 앱에서 가족 연결을 미리 해 두시면 접수와 예약이 수월합니다. 다른 병원에서 받은 검사 결과지나 영상 자료가 있으면 함께 가져오시면 중복 검사를 줄이는 데 도움이 됩니다.\n\n병원은 가온빌딩 3층입니다. 예약 시간보다 조금 일찍 도착해 접수해 주세요. 앱 예약 화면의 QR 코드를 3층 접수처 단말에 대면 바로 접수되고, QR 접수가 어려우시면 원무 창구에서 도와드립니다.\n\n예약이 확정되면 방문 전에 앱에서 간단한 사전문진을 작성하실 수 있습니다. 작성한 내용은 진료 시 담당 의사에게 전달되며, 도착·대기 중에는 수정할 수 있고 진료가 시작되면 읽기 전용이 됩니다. 미리 작성해 두시면 진료가 한결 매끄럽습니다.\n\n지하 주차장은 최초 30분 무료이며 진료 시 1층 원무 창구에서 무료 등록을 도와드립니다. 대중교통은 지하철 3호선 가온역 2번 출구에서 도보 약 5분 거리이고, 101번·203번 버스도 병원 앞 정류장에 정차합니다.\n\n진료 소요 시간은 진료과와 검사 여부에 따라 다릅니다. 순서가 되면 앱 알림과 대기 화면으로 안내해 드리니, 대기 중에는 3층 대기실에서 편하게 기다려 주세요. 잠시 자리를 비우실 때는 접수처에 말씀해 주시면 순서를 조정해 드립니다.', false, 3),
  ('진단서·증명서 등 서류 발급 종합 안내','자주 묻는 질문', E'병원에서는 진단서, 소견서, 진료확인서(통원확인서), 진료비 납입확인서, 진료비 세부내역서 등 여러 서류를 발급해 드립니다. 필요하신 서류의 이름을 잘 모르시더라도 어디에 제출하는지(회사·보험사·관공서 등)를 말씀해 주시면 알맞은 서류를 안내해 드립니다.\n\n서류 발급은 진료 후 3층 원무 창구에서 신청하실 수 있습니다. 진단서·소견서처럼 의사의 작성이 필요한 서류는 담당 의사의 확인을 거쳐 발급되므로 시간이 조금 더 걸릴 수 있고, 진료비 납입확인서나 세부내역서처럼 창구에서 바로 발급되는 서류도 있습니다.\n\n서류를 받으실 때는 본인 확인을 위해 신분증이 필요합니다. 발급된 서류에는 개인정보와 진료 정보가 담기므로 본인 또는 정당한 권한이 있는 분에게만 드립니다.\n\n가족이나 대리인이 대신 받으실 때는 환자 본인의 신분증 사본, 대리인의 신분증, 그리고 위임장이 필요합니다. 배우자나 직계 가족은 가족관계를 확인할 수 있는 서류로 갈음할 수 있으니, 방문 전 원무과에 필요한 서류를 확인하시면 두 번 걸음을 더실 수 있습니다.\n\n서류 종류에 따라 소정의 발급 수수료가 있을 수 있으며, 자세한 금액은 원무 창구에서 안내해 드립니다. 이미 받으신 서류를 잃어버려 다시 필요하시면 재발급도 가능합니다.', false, 3),
  ('가온병원 앱 사용 완전 안내','앱·디지털 이용', E'가온병원 앱은 앱스토어나 구글 플레이에서 ‘가온병원’으로 검색해 설치하실 수 있습니다. 회원가입은 휴대폰 본인확인을 거쳐 진행되며, 가입하시면 예약·접수·알림·사전문진 같은 기능을 모두 이용하실 수 있습니다. 처음 한 번만 가입해 두시면 다음부터는 로그인만으로 이용하실 수 있습니다.\n\n로그인은 가입하신 휴대폰 번호와 비밀번호로 하실 수 있습니다. 비밀번호가 기억나지 않으시면 로그인 화면의 비밀번호 찾기에서 휴대폰 본인확인을 거쳐 새로 설정하실 수 있으니, 창구에 오지 않으셔도 됩니다.\n\n진료 예약은 진료과·날짜·시간을 차례로 골라 신청합니다. 원하시는 시간이 이미 마감된 경우 대기 신청을 해 두시면 취소분이 생길 때 앱 알림으로 안내해 드리며, 알림을 받으시면 정해진 시간 안에 확정해 주세요. 앱 사용이 어려우시면 3층 원무 창구에서 도와드립니다.\n\n예약 내역은 앱의 내 예약에서 확인하실 수 있습니다. 시간을 바꾸시려면 예약 변경, 취소하시려면 예약 취소를 선택하시면 되고, 변경·취소 마감(진료 전날 18시) 이후에는 앱에서 바로 처리되지 않고 상담(직원 확인)으로 연결됩니다. 방문이 어려우실 때는 미리 취소·변경해 주시면 다른 분이 이용하실 수 있습니다.\n\n병원에 오시면 앱 예약 화면의 QR 코드를 3층 접수처 단말에 대어 바로 접수하실 수 있습니다. QR 접수가 어려우시면 원무 창구에서 도와드립니다.\n\n예약이 확정되면 방문 전에 앱에서 간단한 사전문진을 작성하실 수 있습니다. 작성한 내용은 진료 시 담당 의사에게 전달되며, 도착·대기 중에는 수정할 수 있고 진료가 시작되면 읽기 전용이 됩니다.\n\n예약 하루 전과 당일 아침 알림, 순서 안내 등은 앱 알림으로 받으실 수 있습니다. 알림 종류는 앱 설정에서 켜고 끄실 수 있으며, 휴대폰 자체의 알림 권한도 함께 켜 두셔야 알림이 도착합니다.\n\n가족의 진료를 대신 예약하거나 확인하시려면 앱에서 가족 연결을 먼저 진행해 주세요. 연결한 뒤에는 예약할 때 누구의 예약인지 선택할 수 있고, 연결과 해제는 앱 설정에서 관리하실 수 있습니다.\n\n지난 예약과 방문 내역, 병원이 공개한 방문 안내는 앱에서 확인하실 수 있습니다. 다만 자세한 진단기록 전체나 검사 결과의 해석은 진료를 통해 확인하시는 것이 정확합니다.', false, 3),

  -- ── 제한 자료(의료판단 — 봇이 원문만 보여주고 직원 연결) ──
  ('약 복용량 조절 문의','자주 묻는 질문', E'약 복용량 조절은 담당 의사 판단이 필요합니다. 직원 상담으로 연결해 드릴게요.', true, 6),
  ('수술 필요 여부 문의','자주 묻는 질문', E'수술이 필요한지는 진료와 검사를 통한 의사 판단이 필요합니다. 진료 예약을 안내해 드릴게요.', true, 5),
  ('항생제·처방 필요 여부 문의','자주 묻는 질문', E'항생제 등 약 처방 필요 여부는 담당 의사 판단이 필요합니다. 직원 상담으로 연결해 드릴게요.', true, 5),
  ('임신 중 약물·검사 안전성 문의','자주 묻는 질문', E'임신 중 약물·검사 안전성은 담당 의사와의 상담이 필요합니다. 진료 예약을 안내해 드릴게요.', true, 4),
  ('증상 원인·진단 문의','자주 묻는 질문', E'증상만으로 원인이나 병명을 판단하기는 어렵습니다. 진단은 담당 의사 진료가 필요합니다. 진료 예약을 안내해 드릴게요.', true, 4),
  ('약 부작용·상호작용 문의','자주 묻는 질문', E'복용 중인 약의 부작용이나 약끼리의 상호작용은 담당 의사·약사 판단이 필요합니다. 직원 상담으로 연결해 드릴게요.', true, 4),
  ('검사 결과 수치 해석 문의','자주 묻는 질문', E'검사 결과 수치의 의미는 개인의 상태에 따라 달라 담당 의사 진료로 확인하셔야 정확합니다. 진료 예약을 안내해 드릴게요.', true, 4),
  ('치료 방법 선택 문의','자주 묻는 질문', E'어떤 치료가 맞는지는 진료와 검사를 통한 의사 판단이 필요합니다. 진료 예약을 안내해 드릴게요.', true, 4);

  -- 재실행 안전: 같은 title의 이전 적재분 제거(조각 먼저).
  delete from kb_chunks where document_id in (select id from kb_documents where title in (select title from _kb));
  delete from kb_documents where title in (select title from _kb);

  insert into kb_documents (title, category, content, status, is_restricted, created_by, approved_by, approved_at, updated_at)
  select title, category, content, 'approved', restricted, v_admin, v_admin,
         now() - (d || ' days')::interval, now() - (d || ' days')::interval
  from _kb;

  raise notice '대량 KB 적재 완료: % 건', (select count(*) from _kb);
end $$;

-- ══════════════════════════════════════════════════════════════════════════
-- 심화 콘텐츠(2026-09-09) — 얕은 스텁을 한 주제·300~600자·소주제 문단으로 깊게 보강.
--   근거: 평가에서 "답은 맞지만 얕다"(문서에 세부 사실이 아예 없음). chunk_text(max_len 500)에
--   맞춰 한 문서=한 주제=1~2청크로 또렷하게. ⚠️ 진료시간 구체값·의사 개인 스케줄·실시간 예약은
--   DB(intent/도구)가 답하므로 넣지 않고 "물어보세요/앱에서"로 연결만. 진단·처방·복용량 판단 문구
--   금지(제한자료는 원문 그대로 노출되므로 특히). 가온병원(가상)의 일관 사실로 작성.
-- 아래 UPDATE는 위 INSERT의 스텁 content를 덮어쓴다(같은 title). 재임베딩 필요.
-- 배치 1 — 검사 전 준비사항 15건.
-- ══════════════════════════════════════════════════════════════════════════
update kb_documents set content = E'조영제를 사용하는 CT는 검사 4시간 전부터 금식해 주세요. 물은 소량 마셔도 괜찮습니다. 평소 드시던 약은 소량의 물과 함께 복용하셔도 되지만, 당뇨약(특히 메트포르민 성분)은 조영제와 함께 쓰면 주의가 필요하니 복용 여부를 예약 시 꼭 알려 주세요.\n\n조영제·해산물 알레르기가 있었던 분, 신장질환·천식이 있는 분은 예약할 때 미리 말씀해 주세요. 검사 전 신장 기능 확인을 위해 혈액검사를 먼저 할 수 있습니다.\n\n검사 자체는 보통 15~30분 정도 걸립니다. 조영제를 몸 밖으로 잘 내보내도록 검사 후에는 물을 충분히 드세요. 임신 가능성이 있으면 반드시 알려 주세요.\n\n개인의 상태에 따라 준비가 달라질 수 있어, 정확한 안내는 예약하신 검사실이나 직원 상담으로 확인해 주세요.'
  where title = 'CT(조영제) 검사 전 준비';
update kb_documents set content = E'MRI는 강한 자기장을 사용하므로 몸속·몸에 금속이 있으면 미리 알려 주세요. 심박동기, 인공와우, 금속 클립·스텐트, 인공관절, 문신·피어싱, 보청기, 의치 등이 해당합니다. 검사 전 금속이 든 물건(시계·열쇠·카드·머리핀)은 모두 빼 두셔야 합니다.\n\n좁은 통 안에서 20~60분 정도 움직이지 않고 있어야 하며, 검사 중 소음이 큽니다. 폐소공포가 있으시면 예약 시 말씀해 주세요. 필요에 따라 안정을 돕는 방법을 안내해 드립니다.\n\n조영제를 쓰는 MRI는 CT와 마찬가지로 알레르기·신장질환 여부를 확인합니다. 부위에 따라 금식이 필요할 수 있으니 예약하신 검사의 준비사항을 확인해 주세요. 임신 가능성이 있으면 알려 주세요.'
  where title = 'MRI 검사 전 준비·주의사항';
update kb_documents set content = E'갑상선 초음파는 목 부위에 젤을 바르고 초음파 기기를 대어 보는 검사로, 통증이 없고 금식도 필요하지 않습니다. 평소처럼 식사하고 오셔도 됩니다.\n\n검사 시 목이 잘 보이도록 목걸이·목도리 등 목 부위 장신구는 미리 빼 주세요. 폴라티처럼 목을 덮는 옷보다 목이 드러나는 편한 옷이 좋습니다.\n\n검사는 보통 10~20분 정도 걸리며, 끝난 뒤 바로 일상생활이 가능합니다. 결과는 담당 의사 진료에서 설명해 드립니다.'
  where title = '갑상선 초음파 검사 안내';
update kb_documents set content = E'심전도 검사는 가슴과 팔다리에 전극을 붙여 심장의 전기 신호를 보는 검사로, 특별한 준비가 필요 없고 통증도 없습니다. 검사 시 가슴을 드러내야 하므로 위아래가 분리된 편한 옷이 좋습니다. 몇 분이면 끝납니다.\n\n운동부하 검사는 러닝머신을 걸으며 심장 반응을 보는 검사입니다. 편한 운동화와 운동복을 준비해 주시고, 검사 2시간 전에는 과식·흡연·카페인을 피해 주세요. 평소 드시는 약이 있으면 중단 여부를 예약 시 확인해 주세요.\n\n검사는 준비를 포함해 30분~1시간 정도 걸릴 수 있습니다.'
  where title = '심전도·운동부하 검사 안내';
update kb_documents set content = E'폐기능 검사는 마우스피스를 물고 숨을 크게 들이쉬고 내쉬어 폐활량과 기능을 보는 검사입니다. 검사 전 흡연과 과식을 피해 주세요. 천식·만성폐질환으로 흡입약을 쓰신다면 검사 전 사용 여부를 예약 시 확인해 주세요(검사에 따라 잠시 중단할 수 있습니다).\n\n검사 중에는 안내에 따라 숨을 최대한 세게·끝까지 쉬어야 정확합니다. 몇 차례 반복하며 보통 20~30분 걸립니다. 몸이 불편하시면 검사자에게 바로 말씀해 주세요.'
  where title = '폐기능 검사 안내';
update kb_documents set content = E'골밀도 검사는 뼈의 밀도를 측정해 골다공증 위험을 보는 검사로, 낮은 선량의 엑스레이를 사용합니다. 통증이 없고 금식도 필요하지 않으며, 검사대에 누워 있으면 10~15분 안에 끝납니다.\n\n금속이 든 옷(지퍼·단추·버클)이나 장신구는 결과에 영향을 줄 수 있으니 편한 옷을 입고 오시거나 검사 전 벗어 주세요. 최근에 바륨 검사나 조영제 검사를 받으셨다면 며칠 뒤에 하는 것이 좋으니 예약 시 알려 주세요.\n\n임신 가능성이 있으면 반드시 미리 말씀해 주세요.'
  where title = '골밀도 검사 안내';
update kb_documents set content = E'유방촬영(맘모그램)은 유방을 위아래·좌우로 부드럽게 눌러 엑스레이로 촬영하는 검사입니다. 생리 시작 후 일주일 전후에 하면 유방이 덜 예민해 통증이 적습니다.\n\n검사 당일에는 겨드랑이·가슴에 파우더, 데오드란트, 로션을 바르지 마세요. 촬영 상에 점처럼 보여 판독을 방해할 수 있습니다. 위아래가 분리된 옷을 입고 오시면 편합니다.\n\n검사 중 잠시 눌리는 동안 불편할 수 있으나 몇 초면 끝납니다. 유방 확대·수술을 하셨거나 수유 중이시면 예약 시 알려 주세요. 검사는 10~15분 정도 걸립니다.'
  where title = '유방촬영(맘모그램) 검사 안내';
update kb_documents set content = E'경구 당부하 검사는 당뇨를 확인하기 위해 공복 상태에서 당액을 마신 뒤 시간별로 혈당 변화를 보는 검사입니다. 검사 전 8시간 이상 금식해 주세요(물은 소량 가능). 보통 오전에 진행합니다.\n\n먼저 공복 채혈을 하고, 정해진 농도의 당액을 마신 뒤 1~2시간 동안 병원에 머물며 여러 번 채혈합니다. 검사 중에는 흡연·과도한 움직임을 피하고 안정을 유지해 주세요.\n\n전체 소요 시간은 2~3시간 정도입니다. 임신 중이거나 평소 드시는 약이 있으면 예약 시 알려 주세요.'
  where title = '경구 당부하 검사 안내';
update kb_documents set content = E'24시간 활동혈압 검사는 팔에 자동 혈압계를 차고 평소 생활을 하며 하루 동안 혈압 변화를 기록하는 검사입니다. 홀터 검사는 가슴에 작은 심전도 기기를 붙여 24시간 심장 리듬을 기록합니다.\n\n기기를 착용한 채 평소처럼 생활하시되, 기기가 물에 닿지 않도록 샤워·목욕은 피해 주세요. 혈압계가 자동으로 부풀 때는 팔에 힘을 빼고 잠시 멈춰 계시면 정확합니다. 활동과 증상(두근거림·어지럼 등)을 시간과 함께 기록지에 적어 주세요.\n\n다음 날 같은 시간에 기기를 반납하시면 되고, 결과는 담당 의사 진료에서 설명해 드립니다.'
  where title = '24시간 활동혈압·홀터 검사 안내';
update kb_documents set content = E'알레르기 피부반응 검사는 팔이나 등 피부에 여러 알레르기 유발물질을 소량 떨어뜨리고 살짝 자극해 반응을 보는 검사입니다. 검사 전 항히스타민제(알레르기약)나 일부 감기약은 결과에 영향을 주므로, 보통 3~7일 전부터 중단이 필요할 수 있습니다. 복용 중인 약을 예약 시 꼭 알려 주세요.\n\n검사 부위가 잘 보이도록 팔을 걷거나 등을 드러낼 수 있는 옷이 좋습니다. 검사 후 15~20분 정도 반응을 관찰하며, 가려울 수 있으나 긁지 말아 주세요.\n\n스테로이드를 바르거나 드시는 중이면 미리 알려 주세요. 검사 가능 여부와 약 중단은 진료 상담으로 확인해 주세요.'
  where title = '알레르기(피부반응) 검사 안내';
update kb_documents set content = E'위장조영(바륨) 검사는 바륨이라는 조영제를 마신 뒤 엑스레이로 식도·위·십이지장을 보는 검사입니다. 검사 전날 밤 9시 이후에는 물을 포함해 금식해 주세요.\n\n검사 중에는 검사대에서 자세를 여러 번 바꾸며 촬영합니다. 바륨은 맛이 텁텁할 수 있으나 삼키셔야 정확합니다. 검사 후에는 바륨이 잘 배출되도록 물을 충분히 드세요. 며칠간 대변이 하얗게 나올 수 있는데 정상이며, 변비가 생기지 않도록 수분을 넉넉히 섭취해 주세요.\n\n삼키기 어렵거나 장이 막힌 적이 있으신 분, 임신 가능성이 있는 분은 예약 시 꼭 알려 주세요. 개인 상태별 판단은 직원 상담으로 확인해 주세요.'
  where title = '위장조영(바륨) 검사 전 준비';
update kb_documents set content = E'소변검사는 중간뇨를 받아 주세요. 처음 나오는 소변은 버리고 중간에 나오는 소변을 검사용 컵에 받으면 됩니다. 이렇게 해야 오염 없이 정확합니다.\n\n검사 컵은 접수 후 검사실이나 화장실 앞에서 받으실 수 있습니다. 받은 소변은 되도록 빨리 제출해 주세요. 여성은 생리 중이면 결과에 영향이 있을 수 있으니 접수 시 알려 주시고, 필요하면 검사 일정을 조정합니다.\n\n특정 검사는 아침 첫 소변이나 하루 동안 모은 소변이 필요할 수 있으니, 예약하신 검사의 안내를 확인해 주세요.'
  where title = '소변검사 안내';
update kb_documents set content = E'대변 잠혈검사는 대변에 눈에 보이지 않는 피가 섞여 있는지 보는 검사로, 대장암 검진의 기본 검사입니다. 검사실이나 원무 창구에서 채변 용기를 받으실 수 있습니다.\n\n용기에 있는 막대로 대변 표면 여러 곳을 살짝 긁어 소량만 담으면 됩니다. 채취한 검체는 되도록 빨리, 늦어도 하루 안에 제출해 주세요. 실온에 오래 두면 결과가 부정확해질 수 있습니다.\n\n치질로 인한 출혈이나 생리 중에는 결과에 영향을 줄 수 있으니 그 시기를 피하시고, 해당하면 접수 시 알려 주세요. 붉은 고기를 많이 드신 경우도 영향을 줄 수 있습니다.'
  where title = '대변 잠혈검사 안내';
update kb_documents set content = E'검체 채취는 검사 종류에 따라 방법과 준비가 다릅니다. 혈액검사는 팔에서 채혈하며, 공복이 필요한 검사(공복 혈당·지질 등)는 8~12시간 금식 후 진행합니다(물은 가능). 소변·대변은 안내에 따라 직접 받아 제출합니다.\n\n검체 용기는 원무 창구나 검사실에서 받으실 수 있고, 이름·생년월일이 맞는지 확인해 주세요. 채취한 검체는 오염되지 않게 다루고 되도록 빨리 제출해 주세요.\n\n복용 중인 약이나 최근 받은 검사(조영제 등)가 결과에 영향을 줄 수 있으니 예약 시 알려 주세요. 예약하신 검사의 구체적 준비사항은 검사실 안내를 확인해 주세요.'
  where title = '검체 채취 일반 안내';

-- 배치 2 — 위치·주차(7) + 예약·변경·취소(9).
update kb_documents set content = E'지하 2층 주차장을 이용하시면 됩니다. 최초 30분은 무료이며, 이후에는 10분당 500원이 부과됩니다.\n\n진료를 받으신 경우 1층 원무 창구에서 주차 등록을 하시면 2시간 무료 혜택을 받으실 수 있습니다. 등록하실 때 차량 번호를 말씀해 주세요.\n\n정확한 최종 요금은 출차할 때 정산기에서 확인하고 결제하실 수 있으며, 카드와 현금 모두 가능합니다. 장애인·경차·전기차는 별도 감면이 있으니 해당 안내를 참고해 주세요.'
  where title = '주차 요금·정산 안내';
update kb_documents set content = E'장애인 주차구역은 지하 1·2층 주차장 입구와 엘리베이터에서 가까운 곳에 마련되어 있습니다. 장애인 주차가능 표지를 부착한 차량만 이용하실 수 있으며, 표지를 반드시 차량 앞에 보이도록 두세요.\n\n주차 요금은 관련 법령에 따라 감면됩니다. 거동이 불편하시면 1층 안내데스크에 말씀해 주시면 휠체어 대여와 이동을 도와드립니다. 표지가 없는 차량이 이용하면 과태료 대상이 될 수 있으니 일반 구역을 이용해 주세요.'
  where title = '장애인 주차구역 안내';
update kb_documents set content = E'자전거는 지상 1층 건물 옆 거치대에 세워 주세요. 오토바이(이륜차)도 지상 1층 지정 구역을 이용하시면 됩니다. 지하 주차장은 자동차 전용이라 이륜차는 진입할 수 없습니다.\n\n거치대와 이륜차 구역은 무료이며, 도난 방지를 위해 개인 잠금장치를 사용해 주세요. 병원은 분실·도난에 대해 책임지지 않으니 귀중품은 두지 말아 주세요. 자리가 부족하면 1층 안내데스크에 문의해 주세요.'
  where title = '자전거·오토바이 주차 안내';
update kb_documents set content = E'가온병원은 서울특별시 강남구 테헤란로 123 가온빌딩에 있습니다. 접수와 원무 창구는 3층입니다.\n\n지하 1층에는 카페·편의점, 1층 로비에는 안내데스크·현금인출기(ATM)·물품보관함이 있습니다. 3층에는 수유실이 있고, 각 층 안내는 엘리베이터 옆 층별 안내판에서 확인하실 수 있습니다.\n\n처음 오시면 1층 안내데스크나 3층 원무 창구에서 접수를 도와드립니다. 거동이 불편하시면 휠체어를 무료로 빌려 드립니다.'
  where title = '건물·층별 이용 안내';
update kb_documents set content = E'현재 가온역과 병원을 오가는 무료 셔틀버스는 운행하지 않습니다.\n\n대중교통을 이용하시면 편리합니다. 지하철은 3호선 가온역 2번 출구에서 도보 약 5분 거리이고, 버스는 101번·203번을 타고 병원 앞 정류장에서 내리시면 됩니다.\n\n자가용은 지하 2층 주차장을 이용하실 수 있습니다. 거동이 불편하시면 1층 안내데스크에서 도움을 받으실 수 있습니다.'
  where title = '셔틀버스 운행 안내';
update kb_documents set content = E'지하철은 3호선 가온역 2번 출구에서 도보 약 5분 거리입니다. 2번 출구로 나와 큰길을 따라 직진하시면 가온빌딩이 보입니다.\n\n버스는 101번·203번을 이용해 병원 앞 정류장에서 내리시면 됩니다. 정류장에서 건물까지는 도보 1~2분입니다.\n\n무료 셔틀버스는 운행하지 않습니다. 길 찾기가 어려우시면 1층 안내데스크(대표 전화)로 문의해 주세요. 자가용은 지하 2층 주차장을 이용하실 수 있습니다.'
  where title = '대중교통 이용 안내';
update kb_documents set content = E'전기차 충전 구역과 경차 전용 구역은 지하 2층 주차장에 별도로 마련되어 있습니다.\n\n전기차 충전기는 완속 기준으로 운영되며, 충전이 끝난 뒤에는 다른 분을 위해 자리를 비워 주세요. 충전 요금은 사용량에 따라 별도로 부과됩니다.\n\n경차는 관련 규정에 따라 주차 요금이 감면됩니다. 구역이 가득 찼거나 위치를 못 찾으시면 1층 원무 창구나 안내데스크에 문의해 주세요.'
  where title = '전기차·경차 주차 안내';
update kb_documents set content = E'진료 예약은 가온병원 앱에서 가장 편하게 하실 수 있습니다. 앱에서 진료과와 원하는 날짜·시간을 선택해 신청하시면 됩니다. 예약 가능한 시간은 앱에서 실시간으로 확인하실 수 있습니다.\n\n앱 사용이 어려우시면 3층 원무 창구에서 접수 직원이 예약을 도와드립니다. 가족을 대신 예약하려면 앱의 가족(보호자) 연결 기능을 이용하세요.\n\n특정 진료과·담당의의 진료 요일과 시간은 상담봇에 "진료시간 알려주세요"라고 물어보시거나 앱 예약 화면에서 확인하실 수 있습니다.'
  where title = '진료 예약 방법 안내';
update kb_documents set content = E'예약 없이 오셔도 당일 접수로 진료가 가능합니다. 다만 예약 환자가 우선이라 대기 시간이 길어질 수 있습니다.\n\n오시면 3층 원무 창구에서 접수하시고, 진료과와 증상을 말씀해 주세요. 대기 순서와 예상 시간은 접수 시 안내해 드립니다. 진료과에 따라 당일 접수가 조기 마감될 수 있으니, 가능하면 앱 예약을 권장드립니다.\n\n검사가 필요한 경우 당일에 바로 어려울 수 있어 별도 예약을 잡아 드릴 수 있습니다.'
  where title = '당일 접수·현장 진료 안내';
update kb_documents set content = E'원하시는 시간이 모두 예약되어 있으면 대기(취소분 알림) 신청을 하실 수 있습니다. 앱의 예약 화면에서 대기를 신청해 두시면, 그 시간에 취소가 생겼을 때 알림으로 안내해 드립니다.\n\n알림을 받으시면 앱에서 바로 그 자리를 예약하실 수 있습니다. 먼저 신청한 순서대로 기회가 가며, 자리는 선착순이라 알림 후 예약하지 않으면 다음 분에게 넘어갑니다.\n\n대기 알림을 받으려면 앱 알림 설정이 켜져 있어야 합니다.'
  where title = '예약 대기(취소분 알림) 안내';
update kb_documents set content = E'예약한 진료과나 담당 의사를 바꾸고 싶으시면 진료 전날 18시까지 앱의 "내 예약"에서 직접 변경하실 수 있습니다. 원하는 진료과·담당의와 날짜·시간을 다시 선택하시면 됩니다.\n\n마감 시간(전날 18시)이 지난 뒤에는 앱에서 변경이 안 되고, 상담(직원 확인)으로 연결됩니다. 직원이 확인해 가능한 범위에서 도와드립니다.\n\n진료과를 바꾸면 담당 의사와 예약 가능한 시간이 달라질 수 있습니다. 어느 과로 가야 할지 모르시면 증상을 말씀해 주시면 알맞은 진료과를 안내해 드립니다.'
  where title = '진료과·담당의 변경 안내';
update kb_documents set content = E'예약이 완료되면 앱 알림과 함께 예약 내역을 보내 드립니다. 예약 내용은 앱의 "내 예약"에서 언제든 확인하실 수 있습니다.\n\n진료 전날에는 잊지 않도록 안내 알림을 보내 드립니다. 알림을 받으시려면 앱 알림 설정이 켜져 있어야 합니다. 문자 안내를 원하시면 알림 설정에서 선택하실 수 있습니다.\n\n예약이 확인되지 않거나 내역이 보이지 않으면 앱을 새로고침하시거나 3층 원무 창구에 문의해 주세요.'
  where title = '예약 확인·알림 안내';
update kb_documents set content = E'가족을 대신해 예약하시려면 먼저 앱에서 가족(보호자) 연결을 해 두셔야 합니다. 연결된 가족은 앱의 예약 화면에서 대상을 선택해 대신 예약·조회하실 수 있습니다.\n\n가족 연결은 앱의 가족 연결 메뉴에서 상대의 정보를 확인하는 절차를 거쳐 이뤄집니다. 미성년 자녀는 보호자가 연결해 관리하실 수 있습니다.\n\n연결이 어렵거나 대리 예약에 문제가 있으면 3층 원무 창구에서 신분 확인 후 도와드립니다.'
  where title = '보호자 대리 예약·가족 연결 안내';
update kb_documents set content = E'예약을 바꾸시려면 진료 전날 18시까지 앱의 "내 예약"에서 직접 하실 수 있습니다. 다른 날짜·시간으로 옮기거나 진료과·담당의를 변경하실 수 있습니다.\n\n마감 시간(전날 18시)이 지난 뒤에는 앱에서 변경이 안 되고 상담(직원 확인)으로 연결됩니다. 직원이 확인해 가능한 범위에서 도와드립니다.\n\n검사나 특수 진료 예약은 준비가 필요해 변경이 제한될 수 있으니 되도록 일찍 변경해 주세요. 변경 후에는 새 예약 내역을 앱에서 다시 확인해 주세요.'
  where title = '예약 변경 방법 안내';
update kb_documents set content = E'예약을 취소하시려면 진료 전날 18시까지 앱의 "내 예약"에서 직접 취소하실 수 있습니다. 취소하시면 그 자리는 대기 중인 다른 분께 안내됩니다.\n\n마감 시간(전날 18시)이 지난 뒤에는 앱 취소가 안 되고 상담(직원 확인)으로 연결됩니다. 갑자기 못 오시게 되면 되도록 빨리 알려 주시면 다른 분이 이용하실 수 있습니다.\n\n예약 없이 오지 않으시면 부도(노쇼)로 기록될 수 있으니, 취소가 필요하면 미리 처리해 주세요.'
  where title = '예약 취소 방법 안내';
update kb_documents set content = E'예약하신 뒤 취소 없이 오지 않으시면 예약 부도(노쇼)로 기록됩니다. 노쇼는 다른 환자분의 진료 기회를 줄이므로, 못 오시게 되면 전날 18시까지 앱에서 취소해 주세요.\n\n부도가 반복되면 일정 기간 앱 예약이 제한되고 당일 접수만 이용하시게 될 수 있습니다. 자세한 기준은 병원 정책에 따릅니다.\n\n부득이한 사정으로 못 오셨다면 상담(직원 확인)으로 연결해 사정을 말씀해 주세요. 직원이 확인해 안내해 드립니다.'
  where title = '예약 부도(노쇼) 안내';

-- 배치 3 — 건강검진(8) + 예방접종(8).
update kb_documents set content = E'국가건강검진은 국민건강보험공단이 시행하는 검진으로, 일반건강검진과 암검진으로 나뉩니다. 일반건강검진은 만 20세 이상이 보통 2년에 한 번(비사무직 등은 매년) 대상이 됩니다.\n\n대상 여부와 검진 항목은 공단에서 보내는 안내문이나 "건강iN" 누리집·앱에서 확인하실 수 있습니다. 대상이시면 검진센터 예약 후 방문하시면 됩니다.\n\n검진 전날 밤 9시 이후에는 금식이 필요하고, 복용 중인 약이 있으면 예약 시 알려 주세요. 자세한 준비는 검진 예약 안내를 참고해 주세요.'
  where title = '국가건강검진 대상·주기 안내';
update kb_documents set content = E'건강검진은 검진센터에 예약한 뒤 방문하시면 됩니다. 앱이나 3층 원무 창구, 검진센터 전화로 예약하실 수 있습니다.\n\n검진 전날 밤 9시 이후에는 물을 포함해 금식해 주세요(검진 항목에 따라 다를 수 있음). 평소 드시는 약(특히 혈압약·당뇨약·혈액응고제)이 있으면 복용 여부를 예약 시 꼭 확인해 주세요.\n\n검진 당일에는 편한 옷을 입고, 신분증을 지참해 주세요. 위내시경 등 일부 검사는 별도 준비가 필요하니 예약하신 항목의 안내를 확인해 주세요. 개인 상태별 안내는 검진센터나 직원 상담으로 확인해 주세요.'
  where title = '건강검진 예약·준비 안내';
update kb_documents set content = E'위암 검진은 만 40세 이상이 2년마다 위내시경 또는 위장조영(바륨) 검사로 받습니다. 대상 여부는 국민건강보험공단 안내나 건강iN에서 확인하실 수 있습니다.\n\n검사 전날 밤 9시 이후에는 물을 포함해 금식해 주세요. 혈압약 등 꼭 필요한 약은 검사 당일 아침에 소량의 물과 함께 드셔도 되는지 예약 시 확인해 주세요.\n\n수면(진정) 내시경을 원하시면 검사 후 운전이 어려우니 보호자와 함께 오시거나 대중교통을 이용해 주세요. 개인 상태별 안내는 검진센터나 직원 상담으로 확인해 주세요.'
  where title = '위암 검진(위내시경) 안내';
update kb_documents set content = E'대장암 검진은 만 50세 이상이 매년 분변잠혈검사(대변 검사)로 시작합니다. 채변 용기는 검진센터나 검사실에서 받으실 수 있고, 안내에 따라 소량 채취해 가져오시면 됩니다.\n\n분변잠혈검사에서 이상 소견이 있으면 대장내시경을 받게 됩니다. 대장내시경은 검사 3일 전부터 씨앗·견과류·잡곡을 피하고, 전날 저녁부터 장정결제를 복용하는 등 준비가 필요합니다. 자세한 복용 시간은 예약 시 안내해 드립니다.\n\n대상 여부는 국민건강보험공단 안내나 건강iN에서 확인하실 수 있습니다.'
  where title = '대장암 검진 안내';
update kb_documents set content = E'유방암 검진은 만 40세 이상 여성이 2년마다 유방촬영(맘모그램)으로 받습니다. 대상 여부는 국민건강보험공단 안내나 건강iN에서 확인하실 수 있습니다.\n\n생리 시작 후 일주일 전후에 검사하면 유방이 덜 예민해 통증이 적습니다. 검사 당일에는 겨드랑이·가슴에 파우더나 데오드란트를 바르지 마세요.\n\n유방 확대·수술을 하셨거나 수유 중이시면 예약 시 알려 주세요. 검사 결과는 담당 의사 진료나 검진센터 상담에서 설명해 드립니다.'
  where title = '유방암 검진 안내';
update kb_documents set content = E'자궁경부암 검진은 만 20세 이상 여성이 2년마다 받습니다. 자궁경부에서 세포를 채취하는 간단한 검사로 통증이 크지 않습니다.\n\n생리 기간은 피해서 예약해 주세요. 검사 2~3일 전에는 질 세정, 질정 사용, 성관계를 피하시면 결과가 정확합니다.\n\n대상 여부는 국민건강보험공단 안내나 건강iN에서 확인하실 수 있습니다. 결과와 추가 검사가 필요한 경우 담당 의사 진료에서 안내해 드립니다.'
  where title = '자궁경부암 검진 안내';
update kb_documents set content = E'간암 검진은 간암 고위험군(간경변, B형·C형 간염 보유자 등)이 6개월마다 간초음파와 혈액검사(AFP)로 받습니다. 대상 여부는 국민건강보험공단 안내를 확인하시거나 진료 시 상담해 주세요.\n\n간초음파는 검사 전 8시간 정도 금식이 필요할 수 있습니다. 예약하신 항목의 준비사항을 확인해 주세요.\n\n검진 결과 이상 소견이 있으면 추가 검사나 진료 예약을 안내해 드립니다.'
  where title = '간암 검진 안내';
update kb_documents set content = E'건강검진 결과는 보통 검진 후 1~2주 안에 우편이나 앱으로 안내해 드립니다. 결과지는 검진센터나 원무과에서 재발급받으실 수 있습니다.\n\n결과에서 이상 소견(재검·정밀검사 권고 등)이 나오면 추가 검사나 관련 진료과 예약을 안내해 드립니다. 검진센터에서 결과 상담을 받으실 수 있습니다.\n\n결과 수치의 구체적인 의미나 진단은 담당 의사 진료가 필요합니다. 상담봇으로는 결과 해석을 도와드리기 어려워 직원 상담이나 진료로 연결해 드립니다.'
  where title = '검진 후 추가검사·결과 상담 안내';
update kb_documents set content = E'독감(인플루엔자) 예방접종은 매년 유행 전인 가을(보통 10~11월)에 맞는 것이 좋습니다. 접종 후 항체가 생기기까지 약 2주가 걸립니다.\n\n만 65세 이상, 어린이, 임신부 등은 국가에서 무료 접종을 지원할 수 있으니 대상 여부를 확인해 주세요. 접종 가능 시기와 백신 종류는 진료 후 안내해 드립니다.\n\n발열 등 몸이 안 좋을 때는 접종을 미루는 것이 좋습니다. 달걀 알레르기나 이전 접종 이상반응이 있었으면 미리 알려 주세요. 접종 후 15~30분은 병원에 머물며 이상반응을 관찰합니다.'
  where title = '독감(인플루엔자) 예방접종 안내';
update kb_documents set content = E'폐렴구균 예방접종은 폐렴·중이염 등을 일으키는 폐렴구균을 예방합니다. 만 65세 이상은 국가에서 무료 접종(23가 다당질백신)을 지원합니다.\n\n백신 종류(단백결합·다당질)와 접종 간격은 나이와 건강 상태에 따라 다르므로, 진료 후 맞는 종류와 시기를 안내해 드립니다. 만성질환이 있으면 더 일찍 권장될 수 있습니다.\n\n발열 등 몸이 안 좋을 때는 접종을 미루세요. 접종 후 15~30분은 병원에 머물며 이상반응을 관찰합니다.'
  where title = '폐렴구균 예방접종 안내';
update kb_documents set content = E'대상포진 예방접종은 만 50세 이상에게 권장됩니다. 대상포진과 그 합병증인 신경통을 예방하는 데 도움이 됩니다.\n\n백신 종류(생백신·사백신)에 따라 접종 횟수와 간격이 다르므로, 진료 후 맞는 종류와 일정을 안내해 드립니다. 사백신은 보통 2회 접종합니다.\n\n면역이 크게 떨어져 있거나 임신 중이면 접종이 제한될 수 있으니 미리 알려 주세요. 접종 후 15~30분은 병원에 머물며 이상반응을 관찰합니다.'
  where title = '대상포진 예방접종 안내';
update kb_documents set content = E'파상풍 예방접종(Tdap/Td)은 파상풍·디프테리아·백일해를 예방합니다. 기초 접종을 마친 성인은 보통 10년마다 추가 접종을 권장합니다.\n\n녹슨 못에 찔리는 등 상처가 생겼을 때, 마지막 접종이 오래되었다면 추가 접종이 필요할 수 있습니다. 임신부는 매 임신마다 백일해 예방을 위해 Tdap 접종이 권장됩니다.\n\n정확한 접종 시기는 지난 접종 이력에 따라 다르니 진료 후 안내해 드립니다. 접종 후 15~30분은 병원에 머물며 이상반응을 관찰합니다.'
  where title = '파상풍·Tdap 예방접종 안내';
update kb_documents set content = E'A형 간염과 B형 간염 예방접종을 시행합니다. A형 간염은 보통 6개월 간격으로 2회, B형 간염은 0·1·6개월 일정으로 3회 접종합니다.\n\n접종 전 항체 검사가 필요할 수 있습니다. 이미 항체가 있으면 접종하지 않아도 되므로, 진료 시 검사와 접종 여부를 안내해 드립니다.\n\n발열 등 몸이 안 좋을 때는 접종을 미루세요. 접종 후 15~30분은 병원에 머물며 이상반응을 관찰합니다.'
  where title = 'A형·B형 간염 예방접종 안내';
update kb_documents set content = E'자궁경부암(HPV) 예방접종은 사람유두종바이러스로 인한 자궁경부암 등을 예방합니다. 만 12세 여성 청소년은 국가예방접종 지원 대상으로 무료 접종이 가능합니다.\n\n나이와 백신 종류에 따라 2회 또는 3회 접종하며, 정확한 일정은 진료 후 안내해 드립니다. 성별과 관계없이 접종이 권장되는 경우도 있습니다.\n\n임신 중에는 접종을 권장하지 않으니 미리 알려 주세요. 접종 후 15~30분은 병원에 머물며 이상반응을 관찰합니다(어지럼이 있을 수 있어 앉아서 관찰).'
  where title = '자궁경부암(HPV) 예방접종 안내';
update kb_documents set content = E'영유아 국가예방접종은 표준 예방접종 일정에 따라 시행합니다. BCG, B형 간염, DTaP, 폴리오, MMR, 수두, 폐렴구균 등 연령별 접종을 지원합니다.\n\n접종 일정과 이력은 "예방접종도우미" 누리집이나 앱에서 확인하실 수 있고, 병원에서도 조회해 다음 접종을 안내해 드립니다. 아기 수첩(접종 기록)을 가져오시면 도움이 됩니다.\n\n열이 나거나 컨디션이 안 좋으면 접종을 미루세요. 접종 후 15~30분은 병원에서 이상반응을 관찰하고, 귀가 후 고열·심한 보챔이 있으면 진료를 받으세요.'
  where title = '영유아 국가예방접종 안내';
update kb_documents set content = E'예방접종 후에는 15~30분간 병원에 머물며 갑작스러운 이상반응(어지럼·두드러기·호흡곤란 등)이 없는지 관찰합니다. 이상이 느껴지면 바로 직원에게 알려 주세요.\n\n접종 부위는 문지르지 말고 가볍게 눌러 주세요. 접종 당일은 격한 운동과 음주를 피하고, 접종 부위가 붓거나 아프면 차갑게 찜질하시면 도움이 됩니다.\n\n미열·근육통은 흔하며 대개 1~2일 안에 좋아집니다. 39도 이상 고열, 심한 붓기, 호흡곤란 등 심한 증상이 있으면 즉시 진료를 받거나 119에 연락하세요.'
  where title = '접종 후 주의사항 안내';

-- 배치 4 — 입원·퇴원(9) + 응급·야간(4).
update kb_documents set content = E'입원이 결정되면 3층 원무 창구에서 입원 수속을 진행합니다. 신분증과 현재 복용 중인 약 목록(또는 약 봉투)을 준비해 주세요.\n\n수속 시 병실 종류(다인실·상급병실)를 선택하고 입원 서약서 등을 작성합니다. 보증금이 필요할 수 있으며, 실손보험이 있으면 관련 서류를 미리 확인해 두면 편합니다.\n\n입원 후에는 담당 간호사가 병동 생활과 검사·치료 일정을 안내해 드립니다. 궁금한 점은 병동 간호사실에 문의해 주세요.'
  where title = '입원 수속 안내';
update kb_documents set content = E'입원하실 때는 세면도구(칫솔·치약·수건), 개인 물컵, 실내화, 편한 잠옷, 충전기 등을 준비하시면 편합니다. 복용 중인 약이 있으면 약과 함께 약 목록을 가져와 담당 간호사에게 알려 주세요.\n\n신분증과 입원에 필요한 서류, 실손보험 관련 서류도 챙겨 주세요. 기저귀·물티슈 등은 필요에 따라 준비하시고, 병원 내 편의점에서도 구매하실 수 있습니다.\n\n귀중품과 많은 현금은 가져오지 마세요. 분실 위험이 있으며 병원은 책임지지 않습니다. 병실 종류에 따라 준비물이 다를 수 있어 병동 안내를 확인해 주세요.'
  where title = '입원 준비물 안내';
update kb_documents set content = E'병실은 크게 다인실과 상급병실(1~2인실)로 나뉩니다. 다인실은 건강보험이 적용되어 부담이 적고, 상급병실은 별도 차액(비급여)이 발생합니다.\n\n병실은 입원 수속 시 선택하시며, 원하시는 병실이 만실이면 다인실에서 대기 후 옮기실 수 있습니다. 병실별 요금은 원무 창구에서 안내해 드립니다.\n\n감염 관리나 치료상 필요로 병실이 지정될 수 있습니다. 자세한 요금·차액은 비급여 진료비 안내를 참고하시거나 원무 창구에 문의해 주세요.'
  where title = '병실 종류·차액 안내';
update kb_documents set content = E'보호자 상주는 병실과 환자 상태에 따라 안내해 드립니다. 상주 보호자는 병동에서 안내하는 수칙(출입·소등 시간 등)을 지켜 주세요.\n\n간병이 필요하시면 간병인을 두거나 공동간병(간호간병통합서비스) 병동을 이용하실 수 있습니다. 이용 가능 여부와 비용은 병동·원무 창구에서 안내해 드립니다.\n\n감염 예방을 위해 발열·호흡기 증상이 있는 분은 상주·방문을 삼가 주세요. 보호자 교대 시에는 병동에 알려 주세요.'
  where title = '보호자 상주·간병 안내';
update kb_documents set content = E'면회는 정해진 면회 시간에 가능합니다. 감염 예방을 위해 한 번에 방문하는 인원이 제한될 수 있고, 상황에 따라 면회가 조정될 수 있습니다.\n\n발열·기침 등 호흡기 증상이 있으신 분, 어린이는 면회를 삼가 주세요. 면회 시 손 위생을 지키고 필요 시 마스크를 착용해 주세요.\n\n정확한 면회 시간과 병동별 규칙은 해당 병동 간호사실에서 안내해 드립니다. 중환자실 등은 별도의 면회 규칙이 적용됩니다.'
  where title = '면회 시간·규칙 안내';
update kb_documents set content = E'입원 중 식사는 환자의 상태와 치료에 맞춰 제공됩니다. 당뇨식·저염식 등 치료식이 필요하면 담당 의료진이 조정합니다.\n\n검사나 수술을 앞두고 금식이 필요한 경우, 담당 간호사가 금식 시작 시간을 미리 안내해 드립니다. 금식 중에는 물·음식 섭취를 삼가 주세요(허용되는 약은 별도 안내).\n\n외부 음식은 치료에 영향을 줄 수 있어 반입 전 담당 간호사에게 확인해 주세요. 삼킴이 불편하거나 식사가 어려우면 알려 주세요.'
  where title = '입원 중 식사·금식 안내';
update kb_documents set content = E'입원 중에는 낙상(넘어짐)에 주의해 주세요. 침대에서 내려올 때는 천천히 움직이고, 어지러우면 잠시 앉아 안정을 취한 뒤 이동하세요.\n\n미끄럼 방지 실내화를 신고, 바닥에 물이 있으면 밟지 마세요. 침대 난간은 올려 두고, 이동이 어려우면 호출벨을 눌러 도움을 요청하세요. 특히 밤이나 화장실 이용 시 주의가 필요합니다.\n\n어지럼을 일으키는 약을 드시거나 거동이 불편하시면 담당 간호사에게 알려 주세요. 낙상이 발생하면 즉시 알려 주세요.'
  where title = '낙상 예방 안내';
update kb_documents set content = E'퇴원이 결정되면 담당 의료진이 퇴원 시간과 이후 주의사항, 다음 외래 예약을 안내해 드립니다. 퇴원 수속은 3층 원무 창구에서 진행합니다.\n\n진료비를 정산하고 처방전·소견서 등 필요한 서류를 받으시면 됩니다. 실손보험 청구용 서류(진단서·영수증·세부내역서)가 필요하면 원무과에 함께 신청해 주세요.\n\n퇴원 약이 있으면 병원 근처 약국에서 받으실 수 있습니다. 퇴원 후 증상이 나빠지면 안내받은 연락처로 문의하거나 진료를 받으세요.'
  where title = '퇴원 절차·수납 안내';
update kb_documents set content = E'입원 중 외출이나 외박은 치료에 영향을 줄 수 있어 반드시 담당 의료진의 허락을 받아야 합니다. 임의로 병원을 벗어나면 안 됩니다.\n\n허락을 받으시면 외출·외박 신청서를 작성하고, 복용할 약과 돌아올 시간을 안내받습니다. 검사·투약 일정이 있으면 외출이 제한될 수 있습니다.\n\n외출 중 몸 상태가 나빠지면 무리하지 마시고 병원에 연락해 주세요. 정해진 시간에 돌아와 담당 간호사에게 복귀를 알려 주세요.'
  where title = '입원 중 외출·외박 안내';
update kb_documents set content = E'가온병원은 응급실을 운영하지 않습니다. 갑작스러운 심한 증상이 있을 때는 병원 방문을 기다리지 마시고 즉시 119에 전화하거나 가까운 응급실로 가세요.\n\n특히 심한 가슴 통증, 호흡곤란, 갑작스러운 한쪽 마비·발음 이상, 의식 저하, 심한 출혈, 경련은 지체 없이 119에 연락해야 하는 상황입니다.\n\n이 상담봇과 병원 진료는 응급 처치를 대신할 수 없습니다. 응급이 아닌 증상은 진료 예약이나 당일 접수로 진료를 받으시면 됩니다.'
  where title = '응급 증상 대처 안내';
update kb_documents set content = E'가온병원은 야간과 휴일에는 진료를 운영하지 않거나 제한적으로 운영합니다. 요일별 정확한 진료시간은 상담봇에 "진료시간 알려주세요"라고 물어보시거나 앱 예약 화면에서 확인해 주세요.\n\n진료시간 외에 갑작스러운 심한 증상이 있으면 119에 연락하거나 가까운 응급실, 야간·휴일 진료가 가능한 병의원을 이용하세요.\n\n가벼운 증상은 진료시간에 예약하거나 당일 접수로 진료를 받으시면 됩니다. 야간·휴일 약국은 지역 보건소나 관련 안내에서 확인하실 수 있습니다.'
  where title = '야간·휴일 이용 안내';
update kb_documents set content = E'아이가 갑자기 심한 증상을 보이면 기다리지 마시고 즉시 119에 연락하거나 가까운 소아 응급이 가능한 병원으로 가세요. 가온병원은 응급실을 운영하지 않습니다.\n\n특히 축 처지고 반응이 없을 때, 호흡이 힘들거나 입술이 파랗게 될 때, 경련(열성 경련 포함)을 할 때, 심한 탈수(소변이 거의 없고 처짐)일 때는 응급 상황입니다.\n\n38도 이상 발열이라도 아이가 잘 놀고 수분을 먹으면 진료시간에 소아청소년과 진료를 받으셔도 됩니다. 판단이 어려우면 안전하게 119나 응급실을 이용하세요.'
  where title = '소아 응급 대처 안내';
update kb_documents set content = E'약을 먹거나 주사·조영제를 맞은 뒤 두드러기, 얼굴·입술·혀의 붓기, 호흡곤란, 어지럼·실신 같은 증상이 나타나면 심한 알레르기(아나필락시스)일 수 있습니다. 즉시 119에 연락하거나 가까운 응급실로 가세요.\n\n이전에 특정 약·조영제·음식에 알레르기가 있었다면 진료·검사·예약 시 반드시 미리 알려 주세요. 알레르기 카드나 기록이 있으면 지참해 주세요.\n\n가벼운 발진 정도라도 원인 약을 확인해야 하니 진료를 받으시고, 심한 증상은 지체 없이 응급 대응을 하세요.'
  where title = '약물 알레르기 응급 안내';

-- 배치 5 — 앱·디지털(7) + 진료비·증명서(4) + 진료 이용·시간(4).
update kb_documents set content = E'가온병원 앱은 앱스토어(아이폰)나 구글플레이(안드로이드)에서 "가온병원"을 검색해 설치하실 수 있습니다.\n\n설치 후 휴대폰 번호로 본인 인증을 하고 회원가입을 합니다. 이름·생년월일 등 기본 정보를 입력하면 진료 예약, 내 예약 조회, 진료내역·결과 확인, 사전문진, 가족 연결 등을 이용하실 수 있습니다.\n\n인증 문자가 오지 않으면 번호를 다시 확인하시고, 그래도 안 되면 3층 원무 창구에서 도와드립니다. 앱 사용이 어려우시면 창구에서 예약·조회를 대신 도와드립니다.'
  where title = '가온병원 앱 설치·회원가입 안내';
update kb_documents set content = E'앱 로그인은 회원가입 때 등록한 휴대폰 번호와 비밀번호로 하실 수 있습니다. 비밀번호를 잊으셨으면 로그인 화면의 "비밀번호 찾기"에서 휴대폰 인증을 거쳐 새로 설정하시면 됩니다.\n\n인증 문자가 오지 않으면 통신 상태를 확인하고 잠시 후 다시 시도해 주세요. 번호가 바뀌었으면 기존 번호로 인증이 어려우니 3층 원무 창구에서 신분 확인 후 정보를 변경해 드립니다.\n\n로그인이 계속 안 되면 앱을 최신 버전으로 업데이트하거나 원무 창구에 문의해 주세요.'
  where title = '앱 로그인·비밀번호 찾기 안내';
update kb_documents set content = E'가족(보호자) 연결을 하면 앱에서 가족의 예약을 대신 잡고 조회할 수 있습니다. 앱의 가족 연결 메뉴에서 상대 정보를 확인하는 절차를 거쳐 연결합니다.\n\n미성년 자녀는 보호자가 연결해 예약·문진·결과 확인을 관리하실 수 있습니다. 성인 가족은 본인 동의 확인 절차가 필요합니다.\n\n연결된 가족은 예약 화면에서 대상을 선택해 이용하시면 됩니다. 연결 해제도 앱에서 가능합니다. 연결이 어려우면 3층 원무 창구에서 신분 확인 후 도와드립니다.'
  where title = '가족(보호자) 연결 안내';
update kb_documents set content = E'QR 접수를 이용하면 창구에서 기다리지 않고 바로 접수할 수 있습니다. 병원에 도착하시면 앱의 QR 접수 화면을 열거나, 안내데스크·키오스크의 QR 코드를 스캔하세요.\n\n예약이 있으면 QR 접수 시 예약이 확인되어 대기 순서에 등록됩니다. 예약이 없으면 진료과를 선택해 당일 접수할 수 있습니다(대기가 있을 수 있음).\n\nQR 접수가 안 되면 3층 원무 창구에서 접수해 주세요. 사전문진이 있는 진료과는 접수 후 문진 작성을 안내해 드립니다.'
  where title = 'QR 접수 사용법 안내';
update kb_documents set content = E'사전문진은 진료 전에 증상과 병력을 미리 적어 두는 것으로, 진료를 더 정확하고 빠르게 받는 데 도움이 됩니다. 예약 후 앱의 사전문진 화면에서 작성하실 수 있습니다.\n\n증상, 시작 시기, 복용 중인 약, 알레르기, 과거 병력 등을 입력하시면 담당 의료진이 진료 전에 확인합니다. 진료과에 따라 문항이 다를 수 있습니다.\n\n작성한 내용은 저장되며 진료 시 의료진과 공유됩니다. 앱 작성이 어려우면 내원 후 태블릿이나 종이 문진으로도 하실 수 있습니다.'
  where title = '사전문진 작성 안내';
update kb_documents set content = E'앱 알림 설정에서 예약 확인·전날 안내·대기(취소분) 알림 등을 켜고 끌 수 있습니다. 알림을 켜 두시면 예약을 잊지 않고, 취소분이 생겼을 때 빠르게 안내받으실 수 있습니다.\n\n푸시 알림이 오지 않으면 휴대폰 설정에서 가온병원 앱의 알림 권한이 허용돼 있는지 확인해 주세요. 문자 안내를 원하시면 알림 설정에서 함께 선택하실 수 있습니다.\n\n알림 종류별로 개별 설정이 가능하니, 필요한 알림만 켜 두셔도 됩니다.'
  where title = '앱 알림 설정 안내';
update kb_documents set content = E'진료내역과 검사 결과는 앱의 "진료내역·결과" 화면에서 조회하실 수 있습니다. 지난 진료 날짜, 진료과, 처방 내역 등을 확인하실 수 있습니다.\n\n검사 결과는 판독이 끝나면 앱에 올라오며, 검사 종류에 따라 며칠 걸릴 수 있습니다. 결과 수치의 의미나 진단은 담당 의사 진료에서 설명해 드립니다(상담봇은 결과 해석을 도와드리기 어렵습니다).\n\n결과가 보이지 않으면 아직 판독 중이거나 별도 상담이 필요한 경우일 수 있으니 원무 창구나 진료과에 문의해 주세요.'
  where title = '진료내역·결과 앱 조회 안내';
update kb_documents set content = E'진료비는 1층 원무 창구, 무인 수납기(키오스크), 앱에서 수납하실 수 있습니다. 카드, 현금, 간편결제를 이용하실 수 있습니다.\n\n수납 후에는 영수증과 세부내역서를 받으실 수 있고, 앱에서도 내역을 확인하실 수 있습니다. 실손보험 청구가 필요하면 영수증·세부내역서·진단명을 준비해 두세요.\n\n진료비가 부담되거나 한 번에 내기 어려우면 원무 창구에 문의해 주세요. 분할 납부 등 안내를 받으실 수 있습니다.'
  where title = '진료비 수납 방법 안내';
update kb_documents set content = E'진료비 영수증과 세부내역서가 필요하시면 1층 원무 창구나 무인 제증명 발급기, 앱에서 재발급받으실 수 있습니다.\n\n실손보험 청구에는 보통 진료비 영수증, 세부내역서, 진단명(진단서 또는 진료확인서)이 필요합니다. 보험사마다 요구 서류가 다를 수 있으니 미리 확인해 주세요.\n\n오래된 내역도 조회·재발급이 가능하며, 대리 발급 시에는 위임장과 신분증이 필요합니다. 자세한 서류는 증명서·서류 발급 안내를 참고해 주세요.'
  where title = '영수증·세부내역서 재발급 안내';
update kb_documents set content = E'비급여 진료비는 건강보험이 적용되지 않아 환자가 전액 부담하는 항목입니다. 상급병실 차액, 일부 예방접종, 미용·비만 관련 시술, 일부 검사·재료 등이 해당할 수 있습니다.\n\n비급여 항목과 금액은 병원에 안내(고지)되어 있으며, 원무 창구에서 확인하실 수 있습니다. 진료·검사 전에 비급여 여부와 대략의 비용을 안내받으실 수 있으니 궁금하시면 문의해 주세요.\n\n실손보험은 비급여 일부를 보장할 수 있으니 가입하신 보험 약관을 확인해 주세요.'
  where title = '비급여 진료비 안내';
update kb_documents set content = E'진료비를 한 번에 내기 어려우시면 1층 원무 창구에 문의해 주세요. 사정에 따라 분할 납부 등을 안내해 드릴 수 있습니다.\n\n부득이하게 당일 수납이 어려운 경우의 처리(미수납)도 원무 창구에서 절차를 안내해 드립니다. 이후 앱이나 창구에서 정산하실 수 있습니다.\n\n의료비 부담이 큰 경우 이용하실 수 있는 제도(의료급여, 재난적 의료비 등)가 있을 수 있으니 원무 창구나 사회사업 담당에 문의해 주세요.'
  where title = '진료비 분할·미수납 안내';
update kb_documents set content = E'진료와 접수 마감 시간은 진료과와 요일에 따라 다릅니다. 마감이 임박하면 당일 접수가 어려울 수 있으니 여유 있게 오시거나 앱으로 예약해 주세요.\n\n요일별 정확한 진료·접수 시간은 상담봇에 "진료시간 알려주세요"라고 물어보시거나 앱 예약 화면에서 확인하실 수 있습니다. 특정 진료과·담당의의 진료 요일도 함께 확인 가능합니다.\n\n검사가 필요한 진료는 접수 마감이 더 이를 수 있으니 미리 확인해 주세요.'
  where title = '진료·접수 마감 안내';
update kb_documents set content = E'공휴일과 연휴에는 진료를 운영하지 않거나 제한적으로 운영합니다. 명절 등 긴 연휴의 진료 여부는 그때마다 앱 공지나 병원 안내로 알려 드립니다.\n\n휴일 진료 여부와 요일별 시간은 상담봇에 "진료시간 알려주세요"라고 물어보시거나 앱 예약 화면에서 확인해 주세요.\n\n휴일에 갑작스러운 심한 증상이 있으면 119에 연락하거나 가까운 응급실, 휴일 진료가 가능한 병의원·약국을 이용하세요. 가온병원은 응급실을 운영하지 않습니다.'
  where title = '공휴일·연휴 진료 안내';
update kb_documents set content = E'처음 오시는 분(초진)은 접수 시 이름·생년월일·연락처 등 기본 정보를 등록합니다. 앱으로 미리 회원가입과 예약을 해 두시면 더 빠르게 진료받으실 수 있습니다. 신분증을 지참해 주세요.\n\n다시 오시는 분(재진)은 등록된 정보로 바로 접수됩니다. 앱이나 QR 접수를 이용하시면 창구 대기 없이 접수하실 수 있습니다.\n\n다른 병원의 검사·진료 기록(영상 CD, 소견서 등)이 있으면 가져오시면 진료에 도움이 됩니다.'
  where title = '초진·재진 안내';
update kb_documents set content = E'진료는 예약·접수 순서에 따라 진행되지만, 환자 상태나 진료 내용에 따라 순서가 조정되거나 대기가 길어질 수 있습니다. 응급하거나 처치가 오래 걸리는 환자가 있으면 순서가 늦어질 수 있어 양해 부탁드립니다.\n\n대기 순서와 예상 시간은 접수 시, 그리고 진료과 대기 화면에서 확인하실 수 있습니다. 오래 기다리시게 되면 안내데스크나 진료과에 문의해 주세요.\n\n잠시 자리를 비우실 때는 진료과에 알려 주시면 순서를 놓치지 않도록 도와드립니다.'
  where title = '진료 순서·지연 안내';

-- 배치 6 — 증명서·서류 발급(9).
update kb_documents set content = E'진단서는 진료 후 담당 의사가 작성하며, 3층 원무과에 신청하시면 발급해 드립니다. 신청 시 신분증을 지참해 주세요.\n\n종류(일반 진단서, 상해 진단서, 보험용·병사용 등)에 따라 내용과 서식이 달라 발급까지 1~2일이 걸릴 수 있습니다. 어떤 용도로 필요한지 신청 시 말씀해 주시면 맞는 서류로 준비해 드립니다.\n\n본인이 아닌 가족·대리인이 받으시려면 위임장과 가족관계 확인 서류, 대리인 신분증이 필요합니다. 발급 수수료가 있으며 원무과에서 안내해 드립니다.'
  where title = '진단서 발급 안내';
update kb_documents set content = E'진료확인서와 통원확인서는 진료를 받은 사실을 증명하는 서류로, 3층 원무과에서 즉시 발급 가능합니다. 신분증을 지참해 주세요.\n\n회사 제출, 학교·기관 제출, 보험 청구 등 용도에 맞게 발급해 드립니다. 진료 날짜와 통원 횟수가 표시됩니다.\n\n앱이나 무인 제증명 발급기에서도 일부 서류는 바로 발급하실 수 있습니다. 대리 발급 시에는 위임장과 신분증이 필요합니다.'
  where title = '진료확인서·통원확인서 발급';
update kb_documents set content = E'입원확인서와 퇴원확인서는 입원·퇴원 사실과 기간을 증명하는 서류입니다. 3층 원무과에서 발급하며, 보험 청구나 회사·학교 제출에 사용하실 수 있습니다.\n\n신청 시 신분증을 지참해 주세요. 입원 기간과 진료과 등이 표시됩니다. 보험 청구에는 진단명이 필요할 수 있어 진단서·세부내역서와 함께 준비하면 편합니다.\n\n대리 수령 시에는 위임장과 가족관계 확인 서류, 대리인 신분증이 필요합니다.'
  where title = '입원·퇴원 확인서 발급';
update kb_documents set content = E'보험용·병사용 진단서는 일반 진단서와 서식과 내용이 달라, 담당 의사가 용도에 맞게 작성합니다. 3층 원무과에 신청하시면 발급해 드립니다.\n\n보험용은 보험사가 요구하는 항목(진단명·치료 내용·기간 등)이 포함됩니다. 병사용(공무·병역 관련)은 지정 서식이 있을 수 있으니 필요한 서식을 신청 시 알려 주세요.\n\n작성에 진료·검토가 필요해 발급까지 1~2일이 걸릴 수 있습니다. 신분증을 지참하시고, 대리 수령 시 위임장과 관계 서류가 필요합니다.'
  where title = '보험용·병사용 진단서 안내';
update kb_documents set content = E'예방접종 증명서(접종 기록)는 3층 원무과에서 발급하실 수 있습니다. 병원에서 접종한 내역이 표시됩니다.\n\n국가예방접종 기록은 "예방접종도우미" 누리집이나 정부24에서도 조회·발급하실 수 있습니다. 영유아 접종 기록은 아기 수첩으로도 확인할 수 있습니다.\n\n해외 출국·입학·취업 등으로 영문 증명이 필요하면 신청 시 말씀해 주세요. 신분증을 지참하시고, 대리 수령 시 위임장과 관계 서류가 필요합니다.'
  where title = '예방접종 증명서 발급';
update kb_documents set content = E'진료기록 사본은 본인 또는 법정대리인이 3층 원무과에 신청해 발급받으실 수 있습니다. 신청 시 신분증을 반드시 지참해 주세요.\n\n진료기록, 검사 결과, 영상 자료(CD) 등을 발급할 수 있으며, 개인정보 보호를 위해 본인 확인 절차가 엄격합니다. 대리인이 신청하려면 위임장, 가족관계 확인 서류, 위임인·대리인 신분증이 필요합니다.\n\n자료의 양에 따라 준비 시간과 수수료가 다를 수 있으니 원무과에서 안내받으세요. 다른 병원 진료를 위해 필요하면 진료의뢰서(소견서)도 함께 요청하실 수 있습니다.'
  where title = '진료기록 사본 발급 안내';
update kb_documents set content = E'서류를 본인이 직접 받기 어려우면 가족·대리인이 대신 수령하실 수 있습니다. 다만 진단서·진료기록 등 민감한 서류는 본인 확인 절차가 엄격합니다.\n\n대리 수령 시에는 위임장(위임인 서명), 위임인과 대리인의 신분증, 가족관계를 확인할 수 있는 서류(가족관계증명서 등)가 필요합니다. 서류에 따라 추가 확인을 요청할 수 있습니다.\n\n미성년 자녀의 서류는 법정대리인(부모)이 관계 서류와 신분증으로 발급받으실 수 있습니다. 자세한 필요 서류는 원무과에 미리 확인해 주세요.'
  where title = '서류 대리 수령 안내';
update kb_documents set content = E'무인 제증명 발급기(키오스크)에서 진료확인서·통원확인서·영수증·세부내역서 등 자주 쓰는 서류를 직접 발급하실 수 있습니다. 발급기는 1층 로비·원무 창구 주변에 있습니다.\n\n본인 인증(주민등록번호·휴대폰 등) 후 필요한 서류를 선택해 출력하시면 됩니다. 수수료가 있는 서류는 카드로 결제할 수 있습니다.\n\n진단서처럼 의사 작성이 필요한 서류는 발급기에서 나오지 않고 원무과 신청이 필요합니다. 발급기 사용이 어려우면 원무 창구 직원이 도와드립니다.'
  where title = '무인 제증명 발급기 안내';
update kb_documents set content = E'다른(상급) 병원 진료가 필요할 때는 담당 의사가 진료의뢰서(소견서)를 작성해 드립니다. 진료의뢰서가 있으면 상급종합병원에서 진료받을 때 도움이 되고, 건강보험 적용에도 필요할 수 있습니다.\n\n진료 시 상급병원 진료가 필요하다고 판단되면 의뢰서 발급을 안내해 드립니다. 함께 검사 결과나 영상 자료(CD)를 받아 가시면 중복 검사를 줄일 수 있습니다.\n\n의뢰서는 3층 원무과에서 받으실 수 있으며, 어느 병원으로 갈지 정해지면 알려 주세요.'
  where title = '진료의뢰서(상급병원) 안내';

-- 배치 7 — 진료과 안내(14). 각 과가 보는 증상·질환을 사실로 소개(진단 아님). 어느 과일지 애매하면 증상 상담으로 연결.
update kb_documents set content = E'어느 과로 가야 할지 모르시면 상담봇에 증상을 말씀해 주세요. 예를 들어 "무릎이 아파요", "기침이 오래가요", "피부에 두드러기가 났어요"처럼 편하게 말씀하시면 알맞은 진료과를 안내해 드립니다.\n\n증상이 여러 가지거나 어느 과인지 애매하면 내과나 가정의학과에서 먼저 진료받고 필요한 과로 안내받으실 수 있습니다.\n\n진단이 필요한 판단은 의료진의 진료로만 가능합니다. 상담봇은 알맞은 진료과와 병원 이용을 안내해 드리며, 예약은 앱에서 하실 수 있습니다.'
  where title = '어느 과로 가야 할지 안내';
update kb_documents set content = E'내과는 몸 안쪽 장기의 질환을 수술 없이 진료합니다. 소화기(속쓰림·복통·소화불량), 호흡기(기침·가래·감기·천식), 심장·혈압, 당뇨·갑상선 같은 내분비, 신장 등 폭넓은 증상을 봅니다.\n\n감기 몸살, 만성질환(고혈압·당뇨) 관리, 건강검진 결과 상담도 내과에서 진료합니다. 세부 분야(소화기·호흡기·심장 등)로 나뉘어 있어 증상에 맞는 진료를 받으실 수 있습니다.\n\n어느 과인지 애매한 증상은 내과에서 먼저 보고 필요한 과로 안내받으실 수 있습니다. 예약은 앱에서 하실 수 있습니다.'
  where title = '진료과 안내 — 내과';
update kb_documents set content = E'가정의학과는 특정 장기에 국한하지 않고 전반적인 건강 문제를 두루 진료합니다. 어느 과로 가야 할지 애매한 증상, 감기 등 가벼운 질환, 만성질환 관리, 건강검진과 그 결과 상담, 예방접종을 담당합니다.\n\n여러 증상이 겹치거나 처음 어디를 가야 할지 모를 때 가정의학과에서 먼저 진료받고 필요한 전문 과로 안내받으실 수 있습니다.\n\n증상을 말씀해 주시면 가정의학과가 맞을지 다른 과가 맞을지 안내해 드립니다. 예약은 앱에서 하실 수 있습니다.'
  where title = '진료과 안내 — 가정의학과';
update kb_documents set content = E'정형외과는 뼈·관절·근육·인대·힘줄 등 근골격계의 문제를 진료합니다. 허리·목 통증, 무릎·어깨·발목 통증, 골절·삠(염좌), 관절염, 디스크, 스포츠 부상 등을 봅니다.\n\n넘어지거나 부딪혀 다쳤을 때, 관절이 붓고 아플 때, 오래된 통증으로 걷기·움직이기 불편할 때 진료받으시면 됩니다. 필요하면 엑스레이·초음파·MRI 등 검사를 진행합니다.\n\n증상 부위를 말씀해 주시면 정형외과가 맞을지 안내해 드립니다. 예약은 앱에서 하실 수 있습니다.'
  where title = '진료과 안내 — 정형외과';
update kb_documents set content = E'신경과는 뇌와 신경, 근육에서 비롯된 증상을 진료합니다. 두통·어지럼, 손발 저림, 떨림, 어눌한 발음이나 힘 빠짐, 기억력 저하, 경련·발작 등을 봅니다.\n\n갑작스러운 한쪽 마비, 심한 두통, 발음 이상 등 뇌졸중이 의심되는 증상은 응급 상황이므로 기다리지 말고 즉시 119에 연락하거나 응급실로 가세요.\n\n오래가는 두통·어지럼, 저림 등은 신경과 진료를 받으시면 됩니다. 증상을 말씀해 주시면 신경과가 맞을지 안내해 드립니다. 예약은 앱에서 하실 수 있습니다.'
  where title = '진료과 안내 — 신경과';
update kb_documents set content = E'피부과는 피부·모발·손발톱의 문제를 진료합니다. 두드러기·발진·가려움, 여드름, 습진·아토피, 무좀, 대상포진, 탈모, 점·사마귀 등을 봅니다.\n\n갑자기 넓게 두드러기가 올라오며 얼굴·입술이 붓거나 숨쉬기가 힘들면 심한 알레르기일 수 있으니 즉시 119나 응급실을 이용하세요.\n\n가려움·발진이 오래가거나 번질 때, 피부 병변이 변할 때 피부과 진료를 받으시면 됩니다. 증상을 말씀해 주시면 안내해 드립니다. 예약은 앱에서 하실 수 있습니다.'
  where title = '진료과 안내 — 피부과';
update kb_documents set content = E'이비인후과는 귀·코·목의 문제를 진료합니다. 귀 먹먹함·통증·이명·어지럼, 코막힘·콧물·비염·축농증, 목 아픔·편도·목소리 변화, 어지럼증 등을 봅니다.\n\n감기 뒤 오래가는 기침·코막힘, 귀가 안 들리거나 아플 때, 목에 이물감이 지속될 때 진료받으시면 됩니다. 필요하면 내시경·청력검사 등을 진행합니다.\n\n증상을 말씀해 주시면 이비인후과가 맞을지 안내해 드립니다. 예약은 앱에서 하실 수 있습니다.'
  where title = '진료과 안내 — 이비인후과';
update kb_documents set content = E'안과는 눈과 시력의 문제를 진료합니다. 시력 저하·침침함, 눈 충혈·통증·이물감, 눈물·건조, 다래끼, 결막염, 비문증(날파리증), 백내장·녹내장 관련 증상 등을 봅니다.\n\n갑자기 시야가 가려지거나 시력이 급격히 떨어지고 심한 눈 통증이 있으면 지체 말고 진료 또는 응급 대응이 필요합니다.\n\n눈이 불편하거나 시력 검사가 필요하면 안과 진료를 받으시면 됩니다. 증상을 말씀해 주시면 안내해 드립니다. 예약은 앱에서 하실 수 있습니다.'
  where title = '진료과 안내 — 안과';
update kb_documents set content = E'비뇨의학과는 콩팥·방광·요도와 남성 생식기의 문제를 진료합니다. 소변볼 때 아픔·잦은 소변·야간뇨·혈뇨, 요로결석, 방광염, 전립선 관련 증상 등을 봅니다.\n\n소변에 피가 섞이거나 옆구리·아랫배가 심하게 아플 때, 소변이 잘 안 나올 때 진료받으시면 됩니다. 필요하면 소변검사·초음파 등을 진행합니다.\n\n증상을 말씀해 주시면 비뇨의학과가 맞을지 안내해 드립니다. 예약은 앱에서 하실 수 있습니다.'
  where title = '진료과 안내 — 비뇨의학과';
update kb_documents set content = E'산부인과는 여성의 생식기 건강과 임신·출산 관련을 진료합니다. 생리 불순·생리통, 질 분비물·가려움, 아랫배 통증, 자궁·난소 관련 증상, 임신 확인·산전 관리, 폐경기 증상 등을 봅니다.\n\n자궁경부암 검진과 관련 예방접종(HPV)도 안내합니다. 임신 가능성이 있거나 임신 중이면 검사·약 처방 시 미리 알려 주세요.\n\n증상을 말씀해 주시면 산부인과가 맞을지 안내해 드립니다. 예약은 앱에서 하실 수 있습니다.'
  where title = '진료과 안내 — 산부인과';
update kb_documents set content = E'소아청소년과는 영유아부터 청소년까지 아이들의 건강 문제를 진료합니다. 발열·기침·콧물 등 감염 질환, 배앓이·설사·구토, 발진, 성장·발달 상담, 영유아 국가예방접종 등을 봅니다.\n\n아이가 축 처지고 반응이 없거나 호흡이 힘들거나 경련을 하면 응급 상황이니 즉시 119나 소아 응급이 가능한 병원을 이용하세요.\n\n열이 나도 잘 놀고 잘 먹으면 진료시간에 소아청소년과 진료를 받으시면 됩니다. 증상을 말씀해 주시면 안내해 드립니다. 예약은 앱에서 하실 수 있습니다.'
  where title = '진료과 안내 — 소아청소년과';
update kb_documents set content = E'정신건강의학과는 마음의 건강과 관련된 어려움을 진료합니다. 우울·불안, 불면, 심한 스트레스, 공황, 집중력 문제 등을 상담·치료합니다.\n\n혼자 견디기 힘들거나 일상이 어려울 때 진료받는 것은 자연스러운 일입니다. 진료 내용은 비밀이 지켜집니다.\n\n죽고 싶은 생각이 들 만큼 힘드시면 혼자 참지 마시고 즉시 도움을 받으세요. 자살예방 상담전화 109, 정신건강 위기상담 1577-0199에서 24시간 상담을 받으실 수 있고, 위급하면 119에 연락하세요. 예약은 앱에서 하실 수 있습니다.'
  where title = '진료과 안내 — 정신건강의학과';
update kb_documents set content = E'재활의학과는 질병·수술·부상 이후 기능 회복과 통증 관리를 진료합니다. 뇌졸중·골절·수술 후 재활, 목·허리 통증, 근육·관절 재활, 물리치료·도수치료 등을 담당합니다.\n\n다친 뒤나 수술 뒤 움직임이 불편하거나, 오래된 통증으로 일상이 힘들 때 진료받으시면 됩니다. 상태에 맞는 운동·물리치료 계획을 안내합니다.\n\n증상과 경과를 말씀해 주시면 재활의학과가 맞을지, 정형외과·신경과가 맞을지 안내해 드립니다. 예약은 앱에서 하실 수 있습니다.'
  where title = '진료과 안내 — 재활의학과';
update kb_documents set content = E'외과는 수술이 필요할 수 있는 문제를 진료합니다. 배가 아픈 외과 질환(맹장염 등), 탈장, 항문 질환(치질), 갑상선·유방 혹, 상처·종기, 외상 처치 등을 봅니다.\n\n배가 갑자기 심하게 아프거나 상처에서 출혈이 멎지 않으면 지체 말고 진료 또는 응급 대응이 필요합니다. 가온병원은 응급실을 운영하지 않으므로 심한 응급은 119나 응급실을 이용하세요.\n\n혹·상처·복통 등으로 수술 상담이 필요하면 외과 진료를 받으시면 됩니다. 증상을 말씀해 주시면 안내해 드립니다. 예약은 앱에서 하실 수 있습니다.'
  where title = '진료과 안내 — 외과';

-- 배치 8 — 보험·수납(5) + 편의시설(6) + 접근성(4) + 감염관리(3) + FAQ 비제한(8).
update kb_documents set content = E'실손보험(실비) 청구에는 보통 진료비 영수증, 세부내역서, 진단명(진단서 또는 진료확인서)이 필요합니다. 보험사마다 요구 서류가 다를 수 있으니 미리 확인해 주세요.\n\n서류는 1층 원무 창구, 무인 제증명 발급기, 앱에서 발급·재발급하실 수 있습니다. 진단서는 의사 작성이 필요해 원무과 신청 후 1~2일이 걸릴 수 있습니다.\n\n보험금 청구는 서류를 준비해 보험사에 제출하시면 됩니다. 소액은 모바일 앱으로 간편 청구가 가능한 보험사도 있으니 약관을 확인해 주세요.'
  where title = '실손보험 청구 절차 안내';
update kb_documents set content = E'교통사고로 다쳐 자동차보험으로 진료받으시려면, 접수 시 자동차보험 진료임을 말씀하시고 보험사와 접수번호(지불보증)를 알려 주세요.\n\n보험사에서 지불보증이 확인되면 진료비를 자동차보험으로 처리할 수 있습니다. 지불보증이 아직 안 됐으면 우선 본인 부담으로 진료 후 나중에 정산할 수 있습니다.\n\n사고 경위와 상태에 따라 진단서·진료기록이 필요할 수 있습니다. 자세한 절차는 1층 원무 창구에서 안내해 드립니다.'
  where title = '자동차보험(교통사고) 진료 안내';
update kb_documents set content = E'업무 중 다치거나 질병이 생겨 산재보험으로 진료받으시려면, 접수 시 산재 진료임을 말씀해 주세요. 산재 승인 여부와 요양급여 신청 절차에 따라 처리됩니다.\n\n산재 승인 전에는 우선 본인 부담으로 진료 후, 승인되면 정산·환급되는 경우가 있습니다. 회사·근로복지공단을 통한 절차가 필요할 수 있습니다.\n\n필요 서류와 자세한 절차는 1층 원무 창구에서 안내해 드립니다. 사고 경위를 확인할 수 있는 자료를 준비해 주세요.'
  where title = '산재보험 진료 안내';
update kb_documents set content = E'의료급여 수급권자는 의료급여증(또는 자격 확인)으로 진료받으실 수 있습니다. 접수 시 의료급여 대상임을 말씀해 주세요.\n\n의료급여는 본인 부담이 건강보험과 다르며, 1종·2종에 따라 부담금이 다릅니다. 일부 진료·검사는 절차(의뢰 등)가 필요할 수 있습니다.\n\n자격 확인이나 부담금이 궁금하시면 1층 원무 창구에 문의해 주세요. 관련 복지 제도 안내가 필요하면 사회사업 담당에 연결해 드릴 수 있습니다.'
  where title = '의료급여 이용 안내';
update kb_documents set content = E'연말정산 의료비 자료는 국세청 홈택스 "연말정산 간소화 서비스"에서 대부분 자동으로 조회됩니다. 보통 별도로 병원에서 서류를 받지 않아도 됩니다.\n\n간소화 서비스에 자료가 누락되었거나 별도 영수증이 필요하시면, 1층 원무 창구나 무인 제증명 발급기, 앱에서 진료비 영수증·납입확인서를 발급받으실 수 있습니다.\n\n안경·일부 의료기기 등 간소화에 안 잡히는 항목은 구입처 영수증이 필요할 수 있습니다.'
  where title = '연말정산 의료비 안내';
update kb_documents set content = E'원내에는 지하 1층에 카페와 편의점이 있어 간단한 식사·음료·생활용품을 구매하실 수 있습니다. 입원 환자와 보호자, 외래 방문객 모두 이용하실 수 있습니다.\n\n운영 시간은 매장 사정에 따라 다르며, 지하 1층 매장 앞 안내를 참고해 주세요. 병실로의 외부 음식 반입은 치료에 영향을 줄 수 있어, 반입 전 담당 간호사에게 확인해 주세요.\n\n자세한 위치는 1층 안내데스크나 층별 안내판에서 확인하실 수 있습니다.'
  where title = '원내 식당·카페·편의점 안내';
update kb_documents set content = E'현금인출기(ATM)는 1층 로비에 있습니다. 진료비 수납은 카드·현금·간편결제가 가능하니 필요하면 이용해 주세요.\n\nATM 이용 시 타행 수수료 등은 은행 정책에 따릅니다. 위치를 못 찾으시면 1층 안내데스크에 문의해 주세요.'
  where title = '현금인출기(ATM) 안내';
update kb_documents set content = E'물품보관함(코인·전자 라커)은 1층 로비에 있어 짐을 잠시 맡기실 수 있습니다. 이용 방법은 보관함 앞 안내를 참고하시고, 귀중품은 되도록 직접 보관해 주세요.\n\n병원에서 물건을 잃어버리셨으면 1층 안내데스크에 문의해 주세요. 습득물은 안내데스크에서 일정 기간 보관합니다. 분실물을 맡기실 때도 안내데스크로 가져다주시면 됩니다.'
  where title = '물품보관함·분실물 안내';
update kb_documents set content = E'수유실과 기저귀 교환대는 3층에 마련되어 있습니다. 아기와 함께 오신 분이 편하게 이용하실 수 있도록 수유·기저귀 교환 공간을 제공합니다.\n\n이용 중 필요한 것이 있으면 가까운 안내데스크나 간호사실에 말씀해 주세요. 정확한 위치는 층별 안내판이나 1층 안내데스크에서 확인하실 수 있습니다.'
  where title = '수유실·기저귀 교환대 안내';
update kb_documents set content = E'대기실과 병원 내에서 무료 와이파이를 이용하실 수 있습니다. 네트워크 이름은 "GAON-GUEST"입니다.\n\n와이파이에 연결한 뒤 안내 페이지가 뜨면 간단한 동의 절차를 거쳐 이용하시면 됩니다. 연결이 안 되면 와이파이를 껐다 켜거나, 1층 안내데스크에 문의해 주세요.\n\n의료기기 주변 등 일부 공간은 사용이 제한될 수 있습니다.'
  where title = '원내 와이파이 안내';
update kb_documents set content = E'가온병원은 전 구역이 금연입니다. 실내는 물론 건물 출입구 주변에서도 흡연하실 수 없습니다.\n\n흡연이 필요하시면 건물 밖 지정된 흡연구역을 이용해 주세요. 위치는 1층 안내데스크에서 안내해 드립니다. 입원 환자는 치료를 위해 금연이 필요하며, 금연이 어려우면 진료 시 도움을 요청하실 수 있습니다.'
  where title = '금연·흡연구역 안내';
update kb_documents set content = E'거동이 불편하시면 1층 안내데스크에서 휠체어를 무료로 대여해 드립니다. 신분증이나 보증금이 필요할 수 있으니 안내데스크에 문의해 주세요.\n\n이동이 어려운 분은 안내 직원이나 이송 도움을 요청하실 수 있습니다. 휠체어로 이동하기 쉽도록 경사로와 엘리베이터가 마련되어 있습니다.\n\n동행이 없어 이동이 걱정되시면 방문 전 1층 안내데스크에 미리 문의해 주시면 도움을 준비해 드립니다.'
  where title = '휠체어·이동 지원 안내';
update kb_documents set content = E'가온병원은 장애인 편의시설을 갖추고 있습니다. 장애인 주차구역(지하 1·2층), 경사로, 장애인용 엘리베이터와 화장실, 낮은 안내데스크 등을 이용하실 수 있습니다.\n\n휠체어는 1층 안내데스크에서 무료로 대여해 드립니다. 안내견은 원내 동반이 가능합니다.\n\n이동·의사소통에 도움이 필요하시면 안내데스크에 말씀해 주세요. 필요 시 수어·통역 지원도 안내해 드립니다.'
  where title = '장애인 편의시설 안내';
update kb_documents set content = E'한국어 소통이 어려운 외국인 환자나 청각장애가 있으신 분을 위해 통역·수어 지원을 안내해 드립니다. 방문 전 미리 요청하시면 준비에 도움이 됩니다.\n\n필요하시면 1층 안내데스크나 원무 창구에 통역·수어 지원을 요청해 주세요. 전화·화상 통역 등을 연계해 드릴 수 있습니다.\n\n진료 시 의사소통이 어려우면 담당 직원에게 알려 주세요. 정확한 진료를 위해 통역이 함께하도록 돕겠습니다.'
  where title = '통역·수어 지원 안내';
update kb_documents set content = E'시각장애가 있으신 분은 1층 안내데스크에 말씀해 주시면 접수부터 진료·수납까지 안내 직원이 동행해 도와드립니다.\n\n안내견은 원내 동반이 가능합니다. 서류나 안내문을 읽기 어려우시면 직원이 내용을 읽어 드리고 필요한 절차를 대신 도와드립니다.\n\n방문 전 안내데스크에 미리 요청하시면 도움을 준비해 두겠습니다. 이동 중 도움이 필요하면 언제든 직원에게 말씀해 주세요.'
  where title = '시각장애인 안내 지원';
update kb_documents set content = E'감염 예방을 위해 병원 내에서는 상황에 따라 마스크 착용을 권장하거나 요청드릴 수 있습니다. 특히 호흡기 증상이 있으신 분은 마스크를 착용해 주세요.\n\n출입구나 접수 시 발열 여부를 확인(선별)할 수 있습니다. 발열이나 호흡기 증상이 있으면 직원 안내에 따라 별도 동선으로 진료받으실 수 있습니다.\n\n손 위생(손 소독)에 협조해 주시면 나와 다른 환자를 함께 지킬 수 있습니다. 자세한 수칙은 그때의 감염 상황에 따라 안내해 드립니다.'
  where title = '마스크 착용·발열 선별 안내';
update kb_documents set content = E'발열, 기침, 인후통, 콧물 등 호흡기 증상이 있으신 분은 방문 전 이를 알려 주시고, 병원에서는 마스크를 착용해 주세요.\n\n증상이 있으시면 접수 시 직원에게 말씀해 주세요. 다른 환자와의 접촉을 줄이기 위해 별도 대기·진료 동선으로 안내해 드릴 수 있습니다.\n\n증상이 심하거나 갑자기 나빠지면 진료 예약 또는 당일 접수로 진료받으시고, 호흡곤란 등 응급 증상은 119나 응급실을 이용하세요.'
  where title = '호흡기 증상 방문 안내';
update kb_documents set content = E'입원 환자 면회·보호자 방문 시에는 감염 예방 수칙을 지켜 주세요. 발열·기침 등 호흡기 증상이 있으신 분과 어린이는 방문을 삼가 주세요.\n\n면회는 정해진 시간에 가능하며, 한 번에 방문하는 인원이 제한될 수 있습니다. 방문 시 손 위생을 지키고 필요 시 마스크를 착용해 주세요.\n\n병동별 세부 수칙과 면회 시간은 해당 병동 간호사실에서 안내해 드립니다. 감염 상황에 따라 방문이 더 제한될 수 있습니다.'
  where title = '보호자·방문객 수칙 안내';
update kb_documents set content = E'진료 대기시간은 예약·접수 상황과 진료 내용에 따라 달라집니다. 예약 환자가 우선이며, 앞선 환자의 진료가 길어지면 대기가 생길 수 있습니다.\n\n대기 순서와 예상 시간은 접수 시, 그리고 진료과 대기 화면·앱에서 확인하실 수 있습니다. 많이 기다리시게 되면 안내데스크나 진료과에 문의해 주세요.\n\n잠시 자리를 비우실 때는 진료과에 알려 주시면 순서를 놓치지 않도록 도와드립니다. 당일 접수는 예약보다 대기가 길 수 있습니다.'
  where title = '진료 대기시간 안내';
update kb_documents set content = E'가온병원은 원외 처방을 합니다. 진료 후 처방전을 받으시면 병원 근처 약국에서 약을 조제받으실 수 있습니다.\n\n처방전은 종이로 받거나, 진료과에서 안내하는 방식으로 전달됩니다. 처방전에는 유효기간이 있으니 기간 내에 약국을 방문해 주세요.\n\n같은 약을 다시 받으시려면 재진료가 필요할 수 있습니다. 처방전을 잃어버리셨으면 유효기간 내에 원무과에서 재발급받으실 수 있습니다(신분증 필요).'
  where title = '처방약 수령(원외약국) 안내';
update kb_documents set content = E'본인의 개인정보·진료기록 열람이나 정정을 원하시면 3층 원무과에 신청하실 수 있습니다. 본인 확인을 위해 신분증을 반드시 지참해 주세요.\n\n등록된 연락처·주소 등 기본 정보 변경도 원무과에서 하실 수 있습니다. 일부 정보는 앱에서 직접 수정하실 수 있습니다.\n\n대리인이 신청하는 경우 위임장과 가족관계 확인 서류, 대리인 신분증이 필요합니다. 개인정보 보호를 위해 확인 절차가 엄격한 점 양해 부탁드립니다.'
  where title = '개인정보 열람·정정 안내';
update kb_documents set content = E'감염 관리와 다른 환자 보호를 위해 반려동물의 원내 출입은 제한됩니다.\n\n다만 시각장애인 안내견 등 장애인 보조견은 관련 법에 따라 동반하실 수 있습니다. 보조견과 함께 오시면 1층 안내데스크에 말씀해 주세요.\n\n부득이하게 반려동물과 함께 오셔야 하는 사정이 있으면 방문 전 안내데스크에 문의해 주세요.'
  where title = '반려동물 동반 출입 안내';
update kb_documents set content = E'처방전을 잃어버리셨으면 유효기간 안에 한해 3층 원무과에서 재발급받으실 수 있습니다. 재발급 시 신분증이 필요합니다.\n\n유효기간이 지난 처방전은 재발급이 어려워 재진료가 필요할 수 있습니다. 같은 약을 계속 드셔야 하는 경우에는 진료를 통해 다시 처방받으시면 됩니다.\n\n대리 발급 시에는 위임장과 가족관계 확인 서류, 대리인 신분증이 필요합니다.'
  where title = '처방전 재발급 안내';
update kb_documents set content = E'다른 병원에서 받은 검사·진료 기록을 가져오시면 진료에 큰 도움이 되고 중복 검사를 줄일 수 있습니다. 영상 자료(CD), 검사 결과지, 소견서(진료의뢰서), 복용 중인 약 목록 등을 챙겨 오세요.\n\n영상 CD는 접수 시 제출하시면 진료 전에 확인할 수 있도록 준비해 드립니다. 최근 검사일수록 도움이 됩니다.\n\n기록이 없어도 진료는 가능하나, 필요한 검사를 다시 할 수 있습니다. 가능하면 관련 자료를 지참해 주세요.'
  where title = '타 병원 검사기록 지참 안내';
update kb_documents set content = E'외국인 환자도 진료받으실 수 있습니다. 접수 시 여권 등 신분을 확인할 수 있는 서류를 지참해 주세요.\n\n국내 건강보험에 가입되어 있으면(직장·지역가입자, 일정 기간 체류 등) 건강보험 적용을 받으실 수 있습니다. 가입 여부와 자격은 국민건강보험공단에서 확인하실 수 있습니다. 보험이 없으면 비보험(자비) 진료로 진행됩니다.\n\n한국어 소통이 어려우면 통역 지원을 요청하실 수 있으니 방문 전 1층 안내데스크에 문의해 주세요.'
  where title = '외국인 진료·건강보험 안내';
update kb_documents set content = E'진료비는 카드, 현금, 간편결제로 수납하실 수 있으며, 수납은 1층 원무 창구·무인 수납기·앱에서 가능합니다.\n\n현금영수증이 필요하시면 수납 시 요청하시거나, 휴대폰 번호·현금영수증 카드로 발급받으실 수 있습니다. 놓치셨으면 나중에 원무 창구에서 처리해 드립니다.\n\n영수증·세부내역서는 무인 제증명 발급기나 앱에서도 재발급하실 수 있습니다.'
  where title = '현금영수증·카드 결제 안내';

